-- =============================================================================
-- Seed PM quiz questions — Modules 10–18 (15 questions each = 135 total)
-- AI Project Manager & Delivery Leader (pm-v1)
-- Apply AFTER structure and content migrations.
-- Uses direct INSERT (idempotent check by module).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.fill_pm_exam_b(p_mod int, p_payload jsonb)
RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  cid uuid; ch uuid; qz uuid; rec jsonb; i int := 0;
BEGIN
  SELECT id INTO cid FROM public.courses
    WHERE title = 'AI Project Manager & Delivery Leader'
      AND curriculum_version = 'pm-v1';
  SELECT id INTO ch FROM public.chapters
    WHERE course_id = cid AND order_index = p_mod;
  SELECT id INTO qz FROM public.quizzes
    WHERE chapter_id = ch AND quiz_type = 'chapter_end';
  IF qz IS NULL THEN RAISE NOTICE 'no exam for module %', p_mod; RETURN; END IF;
  IF EXISTS (SELECT 1 FROM public.quiz_questions WHERE quiz_id = qz) THEN
    RAISE NOTICE 'module % already has questions — skipping', p_mod; RETURN;
  END IF;
  FOR rec IN SELECT * FROM jsonb_array_elements(p_payload) LOOP
    i := i + 1;
    INSERT INTO public.quiz_questions
      (quiz_id, question_text, options, correct_answer_index, explanation,
       order_index, competency, translations)
    VALUES (qz, rec->>'q', rec->'opts', (rec->>'a')::int, rec->>'exp',
       i, rec->>'competency', '{}'::jsonb);
  END LOOP;
  RAISE NOTICE 'module %: inserted % questions', p_mod, i;
END;
$fn$;

-- ── MODULE 10: Quality Management ────────────────────────────────────────────
SELECT pg_temp.fill_pm_exam_b(10, '[
{"q":"You are a PM on a software project and your sponsor asks you to add a new reporting module that was not in the original scope. The development team says they can build it at no extra cost because they have spare capacity. What is the correct PM response?","opts":["Approve the addition — free capacity means no cost impact","Add it silently to the backlog so the team can work on it","Process a formal change request through the CCB, because adding unrequested features regardless of capacity is gold-plating — it consumes time, introduces defect risk, and bypasses stakeholder trade-off decisions","Refuse any scope additions during execution"],"a":2,"exp":"Gold-plating is adding scope beyond what was approved, even with good intentions or spare capacity. It bypasses change control, exposes the project to defect risk in adjacent functionality, and sets a precedent for informal scope growth. Spare capacity should be directed by the sponsor through the change control process — not consumed by unrequested features.","competency":"pm:quality"},
{"q":"A control chart shows that 4 of the last 7 consecutive data points are all above the mean but still within the Upper Control Limit (UCL). This pattern is known as:","opts":["A random variation — no action required","A special cause signal — the process shows a non-random trend and should be investigated even though no point has breached the control limits","A signal that the UCL must be raised","A natural clustering that proves the process is in control"],"a":1,"exp":"Control charts use run rules: consecutive points on the same side of the mean indicate a non-random special cause even without a limit breach. The process is exhibiting a trend. Investigate the root cause before the trend produces a defect or limit breach. Control limits alone are not the only signal to watch.","competency":"pm:quality"},
{"q":"What is the Pareto principle as applied to quality management, and how does a PM use it?","opts":["80% of projects fail due to 20% of PMs","80% of defects stem from 20% of causes — focus defect elimination efforts on the vital few causes to achieve the greatest quality improvement","Quality costs 80% of the project budget","20% of quality gates catch 80% of defects"],"a":1,"exp":"The Pareto principle tells the PM that fixing the top 20% of root causes will resolve approximately 80% of defects. Build a Pareto chart from defect data: sort defect categories by frequency, identify the dominant categories, and direct root cause analysis and process improvement there first for maximum impact.","competency":"pm:quality"},
{"q":"What is the difference between quality control (QC) and quality assurance (QA)?","opts":["QC is strategic; QA is operational","QA audits processes to ensure they are followed correctly and will produce quality outcomes; QC inspects deliverables and products to identify defects — QA is process-focused, QC is product-focused","QC is performed by the PMO; QA is performed by the development team","They are the same activity with different names"],"a":1,"exp":"QA is proactive: are we using the right processes? Are standards being followed? A QA audit asks whether the testing process is rigorous, not whether a specific test passed. QC is reactive: does this deliverable meet specifications? A QC inspection checks the actual output. Both are required — QA without QC misses defects; QC without QA chases symptoms without fixing root causes.","competency":"pm:quality"},
{"q":"An Ishikawa (fishbone) diagram is used to:","opts":["Map project dependencies in a network diagram","Visually organize potential root causes of a quality problem across categories such as People, Process, Equipment, Materials, Environment, and Method","Track defect counts over time on a Pareto chart","Display process flow from input to output"],"a":1,"exp":"The Ishikawa (cause-and-effect) diagram structures brainstorming around a central problem statement. Teams map contributing causes into standard categories (the ''6 Ms'': Man, Machine, Material, Method, Measurement, Mother Nature). It prevents teams from jumping to solutions before exhausting root cause possibilities.","competency":"pm:quality"},
{"q":"Your project quality management plan commits to a defect escape rate of no more than 2%. At release, you measure 7%. What is the correct PM response?","opts":["Accept the result — targets are aspirational","Blame the testing team and escalate to HR","Conduct a root cause analysis using the 5 Whys or Ishikawa diagram, identify which part of the quality process broke down, implement process corrections for the next release, and report transparently to stakeholders","Lower the quality target retroactively to 8%"],"a":2,"exp":"A quality target breach is a signal of process failure, not just outcome failure. The PM uses root cause analysis tools (5 Whys, fishbone) to trace where in the quality process the defects were introduced and escaped detection. Process corrections — not blame — prevent recurrence and protect future releases.","competency":"pm:quality"},
{"q":"What are the Lean 7 wastes, and which one does a PM most commonly address through better requirement clarity?","opts":["Transportation, Inventory, Motion, Waiting, Overproduction, Over-processing, Defects — Defects is most reduced by clearer requirements","The 7 wastes only apply to manufacturing, not software projects","Lean wastes are identified in DMAIC, not standard PM practice","The 7 wastes are eliminated by adding more testing gates"],"a":0,"exp":"The Lean 7 wastes (TIM WOOD) apply to software: Defects from unclear requirements generate the most expensive waste because the cost of rework scales with how late the defect is found. Clear, testable requirements prevent requirement-originated defects — the most common source of software waste.","competency":"pm:quality"},
{"q":"A PM is preparing for a phase gate review. The quality management plan requires that all critical user stories have passed user acceptance testing before gate approval. Three critical stories have failing UAT results. What should the PM do?","opts":["Approve the gate and fix the stories in the next phase","Mark the failing stories as ''in progress'' to pass the gate","Report the UAT failures accurately to the gate review board, present the defect severity and remediation plan, and recommend the gate be held until the critical stories pass","Re-classify the stories as non-critical to clear the gate"],"a":2,"exp":"Quality gates exist to prevent defects from propagating forward. A PM who manipulates gate data to pass undermines the entire quality framework. The gate review board makes the go/no-go decision with accurate information. A PM who reports failures honestly — with a clear remediation plan — demonstrates professional integrity.","competency":"pm:quality"},
{"q":"What is the PDCA (Plan-Do-Check-Act) cycle, and how does a PM apply it to continuous quality improvement?","opts":["A project lifecycle model for waterfall delivery","A four-step improvement cycle: Plan (identify improvement), Do (implement on small scale), Check (measure results against the plan), Act (standardize if successful or restart if not) — used to iteratively improve quality processes","A cost management framework","A risk response cycle"],"a":1,"exp":"PDCA drives systematic improvement: Plan identifies the quality problem and proposes a solution; Do tests it in a bounded experiment; Check measures whether it worked; Act standardizes the improvement or refines the approach. PMs apply PDCA to retrospective findings, defect reduction initiatives, and process improvements between project phases.","competency":"pm:quality"},
{"q":"A Six Sigma DMAIC project is underway alongside your IT project. In which DMAIC phase would you expect the root cause of defects to be statistically validated?","opts":["Define — the problem is stated","Measure — data is collected","Analyze — statistical tools identify and validate the root cause of the quality problem","Improve — solutions are designed and tested"],"a":2,"exp":"DMAIC: Define (problem statement, scope), Measure (baseline data collection), Analyze (root cause identification using statistical tools — regression, ANOVA, cause-and-effect analysis), Improve (solution design and pilot), Control (sustain the improvement). Root cause validation is the Analyze phase output.","competency":"pm:quality"},
{"q":"What is the ''cost of quality'' and what are its four components?","opts":["The total budget spent on the quality management team","Prevention costs (preventing defects), appraisal costs (inspecting for defects), internal failure costs (defects found before delivery), and external failure costs (defects found by the customer) — the PM optimizes by investing in prevention to reduce more expensive failure costs","Quality costs only include testing expenses","Quality costs are borne exclusively by the vendor"],"a":1,"exp":"Prevention costs (training, process design) are cheapest. Appraisal costs (reviews, testing) are moderate. Internal failure costs (rework before release) are expensive. External failure costs (customer-found defects, warranty, reputation damage) are most expensive. Investing in prevention and appraisal prevents the far costlier failure categories.","competency":"pm:quality"},
{"q":"An AI defect prediction tool analyzes your codebase and identifies three modules with a high predicted defect density based on code complexity metrics. Your testing resources are limited. How should you use this output?","opts":["Ignore it — AI defect prediction is speculative","Immediately rewrite all three modules","Prioritize testing resources toward the three flagged modules, increase test coverage for them, and validate the AI''s complexity analysis with the technical lead before redistributing resources","Apply equal testing effort across all modules to avoid bias"],"a":2,"exp":"AI defect prediction gives the PM a data-driven basis for test resource prioritization — not a directive to rewrite code. Validate the flagged modules with technical experts (is the complexity a real risk or a false positive?), then concentrate testing effort where it will catch the most defects. Equal distribution ignores known risk.","competency":"pm:quality"},
{"q":"The ''5 Whys'' root cause analysis technique involves:","opts":["Identifying five separate root causes for a quality problem","Asking ''Why?'' five times iteratively, each answer becoming the subject of the next ''Why?'' — drilling past symptoms to the true underlying root cause","A committee of five people analyzing quality data","Waiting five days before responding to a quality incident"],"a":1,"exp":"5 Whys: Defect escaped testing → Why? Test cases did not cover this scenario → Why? Requirements were ambiguous → Why? Requirements review was skipped → Why? Schedule pressure caused the PM to approve skipping → Why? The schedule had insufficient buffer. Root cause: inadequate buffer caused process shortcuts. Solve the root, not the symptom.","competency":"pm:quality"},
{"q":"What is the philosophical difference between the Deming prevention approach to quality and the traditional inspection approach?","opts":["Deming favored more inspections than traditional approaches","The traditional inspection approach finds defects after they are created; the Deming prevention philosophy holds that quality must be built into the process — defects prevented are cheaper than defects found","Deming believed quality was the vendor''s responsibility","There is no practical difference — both produce the same outcomes"],"a":1,"exp":"Traditional inspection: build, then inspect, then fix defects. Deming''s prevention philosophy: design quality into every process step so defects cannot be created. Prevention costs are far lower than detection and correction costs. The PM''s role is to ensure processes prevent defects, not just to fund more testing gates.","competency":"pm:quality"},
{"q":"Your project delivers a system that technically meets all documented requirements but receives poor user satisfaction scores because it is difficult to navigate. This illustrates the difference between:","opts":["Scope creep and gold-plating","Conformance to requirements (the system meets what was specified) and fitness for purpose (the system actually serves the user''s real needs) — a PM must validate both dimensions","QA and QC failures","Prevention costs and appraisal costs"],"a":1,"exp":"Conformance to requirements: does the deliverable match the specification? Fitness for purpose: does the deliverable actually meet the user''s real needs? A system can conform to requirements perfectly yet fail fitness for purpose if the requirements were incomplete or wrong. The PM must validate both through acceptance testing AND user feedback.","competency":"pm:quality"}
]'::jsonb);

-- ── MODULE 11: Agile Project Management ──────────────────────────────────────
SELECT pg_temp.fill_pm_exam_b(11, '[
{"q":"You are a Scrum Master on a product development project. During sprint planning, the Product Owner presents stories representing 60 story points for a 10-day sprint, but the team''s average velocity is 40 story points. What should you facilitate?","opts":["Accept all 60 points — the team should stretch","Let the team commit only to what they can confidently complete within the sprint based on velocity, typically around 40 points","Let the Product Owner decide how many stories are in the sprint","Accept 60 points and plan overtime"],"a":1,"exp":"Sprint planning should result in a realistic sprint goal. The team pulls work based on their established velocity — not the PO''s wish list. A team that consistently over-commits burns out and erodes trust. Pulling approximately 40 points establishes a sustainable pace and builds the credibility that enables future velocity improvements.","competency":"pm:agile"},
{"q":"What is the primary purpose of a Kanban WIP (Work In Progress) limit?","opts":["To limit the number of team members on a project","To cap the number of items in any given workflow stage, exposing bottlenecks and forcing the team to finish work before starting new work — improving flow and reducing cycle time","To limit the total project budget","To restrict the number of daily standup participants"],"a":1,"exp":"WIP limits prevent the ''start everything, finish nothing'' pattern. When a stage is at WIP limit, no new work can enter until an item moves forward — making bottlenecks visible. Teams that respect WIP limits reduce cycle time, improve quality (less context-switching), and deliver value faster.","competency":"pm:agile"},
{"q":"What is the difference between cycle time and lead time in Agile delivery?","opts":["They are the same metric with different names","Lead time measures from when a request is made until it is delivered; cycle time measures from when work actually begins until it is delivered — cycle time is always less than or equal to lead time","Cycle time includes wait time; lead time does not","Lead time applies to Kanban; cycle time applies to Scrum"],"a":1,"exp":"Lead time: customer request → delivery (includes queue time). Cycle time: work starts → delivery. The gap between them is queue/wait time — often the largest improvement opportunity. Reducing cycle time improves team efficiency; reducing lead time improves customer responsiveness. Both metrics matter in a healthy Agile system.","competency":"pm:agile"},
{"q":"In a SAFe Program Increment (PI) Planning event, what is the primary output?","opts":["Individual team sprint plans for the next 2 sprints","PI Objectives: team-level and program-level commitments for the next 8–12 weeks, a program board showing cross-team dependencies and risks, and committed PI objectives accepted by Business Owners","A finalized product roadmap for the next 2 years","A prioritized backlog for all teams to pull from independently"],"a":1,"exp":"PI Planning aligns all Agile Release Train teams around a shared program increment goal. Key outputs: (1) team PI objectives (committed and stretch), (2) a program board visualizing cross-team dependencies, (3) risks identified and ROAMed (Resolved, Owned, Accepted, Mitigated). Business Owners score confidence at the end.","competency":"pm:agile"},
{"q":"What distinguishes a sprint retrospective from a sprint review?","opts":["They are the same meeting with different names","Sprint review demonstrates the completed increment to stakeholders and gathers feedback; sprint retrospective focuses internally on how the team worked — process, collaboration, and improvement actions","Sprint retrospective involves stakeholders; sprint review is internal","Sprint review is optional in Scrum; retrospective is mandatory"],"a":1,"exp":"Sprint review = external: show what was built, get stakeholder feedback, update the backlog. Sprint retrospective = internal: what went well, what did not, what will we improve? Both are mandatory Scrum ceremonies. Retrospectives without concrete action items are wasted effort.","competency":"pm:agile"},
{"q":"The Agile Manifesto values ''responding to change over following a plan.'' A stakeholder interprets this as meaning the team should accept any change request at any time during a sprint. How do you correct this misunderstanding?","opts":["The stakeholder is correct — no planning should exist in Agile","Agree and allow all changes mid-sprint to demonstrate Agile flexibility","Clarify that the Manifesto values adaptability at the product and release level, not sprint-level chaos — mid-sprint changes disrupt flow, prevent commitment-based planning, and undermine the team''s ability to deliver; changes are captured in the backlog and prioritized by the PO for future sprints","Ban all changes until the project ends"],"a":2,"exp":"The Agile Manifesto does not endorse continuous disruption. Sprints provide a commitment boundary: the team focuses on the sprint goal for 1–2 weeks. New requests go to the PO-managed backlog and are prioritized for the next sprint. Urgent changes may justify sprint cancellation — but that is an exception, not standard practice.","competency":"pm:agile"},
{"q":"A cumulative flow diagram (CFD) for your Kanban team shows the ''In Progress'' band widening significantly over the past two weeks while ''Done'' remains flat. What does this indicate?","opts":["The team is accelerating delivery","Work is piling up in progress — the team is starting work faster than it is completing work, indicating a bottleneck or WIP limit being exceeded","The backlog is being refined effectively","The team''s velocity is increasing"],"a":1,"exp":"A widening ''In Progress'' band is the CFD signature of a WIP problem or downstream bottleneck. Items are being started but not completed. The PM investigates: Is there a specific stage causing the jam? Are WIP limits being ignored? The fix is to stop starting new work and focus on clearing the jam.","competency":"pm:agile"},
{"q":"In Scrum, who is responsible for removing impediments that are outside the team''s control?","opts":["The Product Owner","The Development Team","The Scrum Master — whose primary accountability to the team is identifying and removing organizational impediments that block team progress","The PMO"],"a":2,"exp":"The Scrum Master is the team''s servant-leader and organizational impediment remover. If a team is blocked by a procurement process, an access approval, or an organizational policy, the Scrum Master escalates and navigates the organization to remove the block — the team should not have to wait or self-navigate organizational friction.","competency":"pm:agile"},
{"q":"Your team''s velocity has been 45, 42, 48, and 44 story points over the last 4 sprints. The product backlog has 320 points remaining. How many sprints will it likely take to complete the product?","opts":["Exactly 7 sprints — divide 320 by average velocity of 45.7","7–8 sprints, based on average velocity of approximately 45 — the actual range carries inherent uncertainty that increases as the time horizon extends","3 sprints — the team can double velocity with effort","Impossible to forecast from velocity data alone"],"a":1,"exp":"Release forecast: 320 / 45 ≈ 7.1 sprints, so 7–8 sprints is a reasonable range. Velocity is historical, not guaranteed — scope changes, team changes, and technical complexity affect it. Communicate the forecast as a range with explicit uncertainty. Update the forecast each sprint as velocity data accumulates.","competency":"pm:agile"},
{"q":"What is the Definition of Done (DoD) in Scrum, and how does it differ from acceptance criteria?","opts":["DoD and acceptance criteria are the same thing","DoD is a shared team standard for what every increment must meet to be considered releasable (e.g., unit tested, code reviewed, documented, deployed to staging); acceptance criteria are story-specific conditions defined by the PO that the story must satisfy","DoD is set by the sponsor; acceptance criteria are set by the team","DoD applies only to the final product release; acceptance criteria apply to each sprint"],"a":1,"exp":"DoD is universal: every story must meet the DoD before it is ''done'' — code review passed, tests passing, documentation updated. Acceptance criteria are specific to each story: ''User can filter results by date range.'' A story can meet its acceptance criteria but fail the DoD (if tests are missing). Both must be satisfied.","competency":"pm:agile"},
{"q":"In LeSS (Large-Scale Scrum), how does the framework handle multiple teams working on the same product?","opts":["Each team has its own Product Owner and separate product backlog","There is one Product Owner, one Product Backlog, and one Sprint for all teams — teams self-select work from the shared backlog each sprint, with shared sprint review and retrospective events","LeSS uses a hierarchy of Scrum Masters to coordinate teams","Teams work independently with quarterly sync events"],"a":1,"exp":"LeSS scales Scrum by preserving single-team Scrum fundamentals: one PO, one backlog, synchronized sprints. Multiple teams pull from the same backlog each sprint, enabling cross-team coordination without creating separate product silos. The Overall Retrospective coordinates multi-team process improvements.","competency":"pm:agile"},
{"q":"An AI sprint intelligence tool predicts a 30% probability of missing the sprint goal with 5 days remaining. Three stories are still in progress. What should the PM/Scrum Master do?","opts":["Ignore the AI prediction — the team will self-organize","Cancel the sprint","Discuss the prediction with the team in the daily standup: identify which stories are at risk, evaluate whether scope reduction is necessary to protect the sprint goal, and take action transparently","Extend the sprint by 2 days to compensate"],"a":2,"exp":"A risk-informed daily standup with AI prediction as context enables the team to make an informed scope decision. Protecting the sprint goal may require removing a lower-priority story from the sprint — better to deliver 2 stories completely than 3 stories partially. Extending sprints disrupts the cadence and avoids the underlying problem.","competency":"pm:agile"},
{"q":"What is Scrum of Scrums, and when is it used?","opts":["A scaled Scrum ceremony where representatives from multiple Scrum teams meet regularly to coordinate cross-team dependencies, impediments, and integration points — typically used when 3 or more teams work on the same product","A type of retrospective for large teams","A SAFe event replacing PI Planning","A technique for managing product owner priorities across teams"],"a":0,"exp":"Scrum of Scrums is a coordination mechanism for multi-team delivery. Each team sends a representative (typically a technical lead or Scrum Master). Agenda: What did we do that might affect another team? What will we do? What blocked us? The SoS resolves cross-team impediments that cannot be resolved within a single team''s standup.","competency":"pm:agile"},
{"q":"A hybrid delivery model combines a waterfall stage-gate for regulatory sign-off with Agile sprints for development. A sprint produces a feature that requires regulatory review before the next sprint can build on it. How should the PM handle this dependency?","opts":["Abandon the hybrid model and go fully waterfall","Ignore the regulatory dependency and continue sprinting","Treat the regulatory review as a planned gate in the hybrid schedule: build the review period into the release plan as a non-sprint activity, ensure the feature is ready for submission at sprint end, and manage the gate timeline with the regulatory stakeholder separately from the sprint cadence","Ask the development team to handle regulatory submissions"],"a":2,"exp":"Hybrid delivery requires explicit management of the interfaces between adaptive and predictive elements. Regulatory gates are predictive: they have fixed process requirements and timelines. The PM owns the gate timeline and integrates it into the release plan, while the team continues sprinting on non-dependent work during the review period.","competency":"pm:agile"},
{"q":"Which Agile Manifesto value addresses the PM''s instinct to rely on process and tools over team collaboration?","opts":["Working software over comprehensive documentation","Customer collaboration over contract negotiation","Responding to change over following a plan","Individuals and interactions over processes and tools — valuing the people and their collaboration above any framework or toolset"],"a":3,"exp":"''Individuals and interactions over processes and tools'' directly addresses the tendency to optimize the toolset (Jira configuration, process playbooks) instead of investing in team relationships, communication, and collaboration. Tools support people; they do not substitute for them. PMs who over-engineer processes at the expense of human dynamics undermine Agile''s foundation.","competency":"pm:agile"}
]'::jsonb);

-- ── MODULE 12: Change Management ─────────────────────────────────────────────
SELECT pg_temp.fill_pm_exam_b(12, '[
{"q":"You are a PM deploying a new ERP system. Resistance is high among the finance team. Using the ADKAR model, you determine that employees understand why the change is happening (Awareness) but do not want to change (low Desire). What intervention is most appropriate?","opts":["Send more awareness communications about the system benefits","Deliver technical training on how to use the new system","Focus on WIIFM: conduct manager-led conversations addressing personal impact concerns, involve vocal resistors in the design of the transition, and demonstrate early successes from peer champions","Announce that system use is mandatory and resistance will be documented"],"a":2,"exp":"ADKAR is sequential: Awareness is present, so re-communicating why will not help. Desire is the gap — people must want to change. WIIFM conversations, peer champions who demonstrate positive impact, and involvement in transition design build Desire. Mandates create compliance, not genuine adoption.","competency":"pm:change-management"},
{"q":"Kotter''s 8-step model for leading change begins with creating a sense of urgency. On a technology migration project, the organization feels the current system is ''good enough.'' What technique best creates urgency?","opts":["Announce a hard cutover date and withdraw support for the old system","Show data: cost of the status quo (system maintenance cost, downtime incidents, competitor capability gap) and the risk of not changing — making the case that inaction is more dangerous than the migration","Send executive memos declaring the project a high priority","Hire external consultants to validate that the change is needed"],"a":1,"exp":"Kotter Step 1: Urgency must be data-driven, not manufactured. Show the cost of the current state: system outage frequency, maintenance cost trajectory, security vulnerability exposure, and competitive capability gap. When stakeholders see inaction''s cost clearly, urgency emerges from evidence rather than top-down mandate.","competency":"pm:change-management"},
{"q":"What is the difference between change management and project management?","opts":["They are the same discipline","Project management focuses on the technical side of change (deliverables, schedule, cost, quality); change management focuses on the people side (adoption, behavior change, resistance, capability building) — both are required for successful transformation","Change management is only needed for failed projects","Project management is for external delivery; change management is for internal culture"],"a":1,"exp":"Research finding: 70% of change initiatives fail due to people factors, not technical failures. Project management delivers the solution; change management ensures people adopt it. Without both, organizations get systems that are built but not used. The PM must coordinate both tracks, even if a dedicated change manager leads the people side.","competency":"pm:change-management"},
{"q":"You are 90 days post-go-live on a CRM deployment. Adoption metrics show only 45% of sales reps are logging activities in the new system. What is the most likely root cause according to the ADKAR model?","opts":["Awareness gap — salespeople do not know the system exists","Desire gap — sales reps see logging activities as extra work with no personal benefit","Knowledge gap — they do not know how to use the system","Reinforcement gap — managers are not inspecting CRM usage in pipeline reviews or holding reps accountable for data quality"],"a":3,"exp":"90 days post-go-live with 45% adoption despite training suggests a Reinforcement gap. If managers do not reference CRM data in pipeline reviews, reps receive no consequence for non-use. Reinforcement closes the adoption gap: incorporate CRM data into performance reviews, pipeline meetings, and sales coaching — making use expected and visible.","competency":"pm:change-management"},
{"q":"What is a change champion network and what role does it play in a large-scale change initiative?","opts":["A group of executives who approve all changes","A network of influential peers (not managers) embedded in the affected business units who advocate for the change, support colleagues through the transition, provide feedback to the project team, and model the new behaviors","A committee of change managers who govern the project","A technical working group that validates system changes"],"a":1,"exp":"Change champions are peer influencers — people respected in their business unit who choose to support the change. They are more effective than management mandates because peer influence drives behavior change more reliably than authority. The PM recruits champions early, equips them with messaging and tools, and recognizes their contribution.","competency":"pm:change-management"},
{"q":"A post-implementation survey shows that 60% of users rate their proficiency with the new system as ''low'' despite attending 4-hour training sessions. What does this most likely indicate?","opts":["The system is too complex and should be redesigned","The training was scheduled too far in advance of go-live — users learned skills they could not immediately apply, leading to knowledge decay before they needed the skills","The users are resistant and need to be mandated","4 hours of training is always insufficient for any system"],"a":1,"exp":"Training effectiveness is timing-sensitive. Classroom training 6 weeks before go-live results in significant knowledge decay by the time users need the skills. Best practice: train close to go-live (within 1–2 weeks), use role-based training focused on real job tasks, provide job aids for the first 90 days, and supplement with floor-walking support at go-live.","competency":"pm:change-management"},
{"q":"How is change management ROI typically measured?","opts":["By the number of change management activities completed","By the speed of go-live","Through adoption metrics (utilization rate, proficiency rate, business outcome metrics such as productivity, error rate reduction, or revenue per user) compared to the baseline before change","By stakeholder satisfaction survey scores alone"],"a":2,"exp":"Change ROI measurement: utilization rate (are people using the system?), proficiency rate (are they using it correctly?), and business outcome metrics (did productivity improve, did errors decrease, did revenue-per-user increase?). These are measured against pre-change baselines. Without outcome measurement, you can only confirm the system was built — not that it worked.","competency":"pm:change-management"},
{"q":"What is change saturation, and how should a PM respond when the organization is experiencing it?","opts":["When too many stakeholders approve change requests","When the organization is experiencing so many simultaneous change initiatives that people cannot effectively absorb and adopt them all — leading to fatigue, resistance, and adoption failure across all initiatives","A technical term for too many software updates","When change management activities exceed the project budget"],"a":1,"exp":"Change saturation occurs when organizations run too many concurrent transformations. Symptoms: declining engagement scores, rising resistance, adoption metrics stalling. PM response: work with the PMO or portfolio governance to sequence changes, defer non-critical projects, and communicate a realistic timeline. Adding more change management resources to a saturated organization does not help — the bottleneck is organizational absorptive capacity.","competency":"pm:change-management"},
{"q":"You are designing the communication campaign for a digital workplace transformation affecting 2,000 employees across 5 business units. What communication principle should guide your campaign design?","opts":["Send one universal message to all 2,000 employees simultaneously","Use the most advanced technology channels regardless of employee access","Segment the audience by business unit and role, tailor messages to address each segment''s specific WIIFM and concerns, use a multi-channel approach (email, team meetings, intranet, manager cascade), and sequence communications from high-level awareness through detailed how-to","Limit communications to official memos only"],"a":2,"exp":"Segmented, multi-channel communication outperforms mass messaging. A finance analyst''s concerns differ from a customer service representative''s. Manager cascade (line managers deliver messages to their teams) is the most effective channel because employees trust their direct manager most. Sequence: why → what → when → how.","competency":"pm:change-management"},
{"q":"What is the sponsor''s role in organizational change management, and why is active sponsorship critical?","opts":["The sponsor approves the budget and has no further role in change","The sponsor is the most important change role: visibly championing the change, participating in communications and town halls, removing organizational barriers, holding managers accountable for adoption, and modeling the new behaviors","The sponsor delegates all change management to the PM","Sponsorship is only needed when resistance is high"],"a":1,"exp":"Research consistently shows that active, visible sponsorship is the single most important factor in change success. Sponsors who approve the budget and disappear create a vacuum that resistance fills. Active sponsors attend town halls, make personal commitments to the change, hold their leadership team accountable for adoption, and are available to resolve organizational barriers.","competency":"pm:change-management"},
{"q":"An AI change impact assessment tool predicts that the Accounts Payable team will experience a 40% workflow disruption. The AP manager was not in the stakeholder register. What should you do?","opts":["Accept the AI prediction and add 40% contingency to the AP go-live schedule","Ignore the finding — AP is a secondary stakeholder","Immediately add the AP manager to the stakeholder register, schedule a discovery session to understand their current workflows, validate the AI''s 40% disruption estimate, and develop a targeted change management plan for the AP team","Send the AI report to the AP manager without context"],"a":2,"exp":"AI change impact analysis is a stakeholder identification input. A 40% workflow disruption prediction for an unengaged team is a critical finding. The PM validates the estimate (is it accurate?), engages the AP manager immediately, and develops a tailored support plan. Discovering this before go-live is the best possible outcome from AI analysis.","competency":"pm:change-management"},
{"q":"A middle manager is technically supportive of the change in steering committee meetings but is observed telling their team that ''this is just another initiative that will blow over.'' How do you address this?","opts":["Ignore it — manager attitudes are outside the PM''s scope","Escalate immediately to the senior sponsor to have the manager removed","Have a private conversation with the manager to understand their specific concerns, address them directly, reinforce the change commitment, and ask for their explicit visible support in team communications — escalating to the sponsor only if the behavior continues and is creating adoption risk","Send an all-staff email reinforcing the change commitment"],"a":2,"exp":"Managers who undermine change in their teams create adoption failure that no amount of training or communications can fix. The PM engages the manager privately (not punitively), diagnoses the specific concern, and works to convert them — or at minimum, establishes a clear professional behavior expectation. Passive resistance from managers is a high-priority change risk.","competency":"pm:change-management"},
{"q":"What is a training needs analysis (TNA) in a change management context?","opts":["An assessment of the project team''s training budget","A systematic analysis of the gap between current employee skills and the skills required to perform effectively in the changed environment — used to design targeted, role-based training rather than one-size-fits-all programs","A review of available training vendors","An assessment of how many training hours are required by compliance"],"a":1,"exp":"TNA maps: current state (what can employees do now?) vs. future state (what must they do in the new environment?). The gap drives training design. Role-based TNA produces targeted programs: front-line staff need process and system skills; managers need coaching skills for supporting their teams through change. Generic training addresses no one''s specific gap.","competency":"pm:change-management"},
{"q":"A team resisting a new workflow automation system says ''our jobs will be eliminated.'' Which change management response is most appropriate?","opts":["Deny that any jobs will be affected","Ignore the concern — it is irrational","Address the fear directly with factual information: clarify which roles will be affected and how, communicate the redeployment or reskilling plan, involve affected employees in redesigning their roles, and provide accurate transition guidance through HR","Announce that automation will increase efficiency and move on"],"a":2,"exp":"Job-loss fear is the most powerful resistance driver. Vague reassurances make it worse. The change management response: be factual about impact, communicate the support plan (reskilling, role redesign, redeployment), involve employees in defining their future role, and give them agency in the transition. Silence or denial creates the worst-case assumptions.","competency":"pm:change-management"},
{"q":"You are designing a 90-day post-go-live sustainability plan for a major system implementation. Which elements are most critical to include?","opts":["Only technical bug fixes and system patches","Floor-walking support in Week 1, help desk coverage metrics, super-user network activation, manager coaching cadence, 30/60/90-day adoption metric reviews, and a recognition program for early adopters — sustaining behavioral change until the new way of working becomes default","A schedule for decommissioning the old system","An executive report on the project budget closeout"],"a":1,"exp":"Post-go-live is where most change initiatives fail — project teams disengage just as users are struggling. Sustainability requires: visible support at go-live (floor walking), escalation paths (help desk), peer experts (super-users), management reinforcement (coaching cadences), and adoption measurement (30/60/90-day metrics). Recognition of early adopters drives peer-level change momentum.","competency":"pm:change-management"}
]'::jsonb);

-- ── MODULE 13: Portfolio & Program Management ─────────────────────────────────
SELECT pg_temp.fill_pm_exam_b(13, '[
{"q":"An investment committee is reviewing 8 proposed projects with limited capital. The organization''s stated priority is strategic growth in a new market. Which portfolio scoring factors should be weighted most heavily?","opts":["Project cost and duration only","Strategic alignment with the new market initiative, expected revenue contribution, market share impact, and resource feasibility — weighted to reflect the organization''s stated strategic priority","Risk rating and technology readiness level only","Number of stakeholders supporting each project"],"a":1,"exp":"Portfolio scoring must reflect the organization''s actual strategy. If the priority is new market growth, strategic alignment and revenue potential carry the highest weight. A project with low cost but no market connection should score lower than a higher-cost project directly enabling the strategic goal. Scoring criteria must be defined before projects are evaluated — not after.","competency":"pm:portfolio"},
{"q":"What is a benefits map (benefits dependency map), and how does a PM use it in program management?","opts":["A financial chart showing cumulative project costs","A visual tool that traces the pathway from project deliverables through enabling changes and business changes to the ultimate organizational benefits — used to identify what must change in the organization for benefits to be realized","A stakeholder map showing who benefits from the project","A Gantt chart showing when benefits will be realized"],"a":1,"exp":"Benefits maps prevent the disconnect between ''we built it'' and ''we realized the benefits.'' They trace: system deliverable → process change → behavior change → business outcome → strategic benefit. If the middle links (process and behavior change) are not managed, the end benefit will not materialize — even if the technical deliverable is perfect.","competency":"pm:portfolio"},
{"q":"A program manager discovers that two projects in the portfolio are planning to build the same data integration layer independently. What should the program manager do?","opts":["Allow both to proceed — parallel development reduces risk","Document the duplication and raise it at the next portfolio review board meeting in 3 months","Immediately convene both project managers to assess whether a shared component can be built by one team and consumed by both, eliminating duplicate cost and reducing integration risk","Escalate to the sponsor without involving the project managers"],"a":2,"exp":"Program management''s primary value over individual project management is identifying and eliminating cross-project waste and risk. Duplicate infrastructure components create: double the build cost, double the maintenance cost, and integration inconsistency. The program manager''s immediate action is to facilitate a shared solution discussion — this is exactly the kind of oversight that justifies program governance.","competency":"pm:portfolio"},
{"q":"What is Weighted Shortest Job First (WSJF) as applied at portfolio level, and what problem does it solve?","opts":["A scheduling algorithm that puts the longest project first","A prioritization formula: Cost of Delay divided by Job Duration — used to sequence portfolio investments based on economic value delivered per unit of time, preventing high-value short-duration items from being deprioritized behind large slow projects","A resource allocation formula for project teams","A risk-adjusted NPV calculation"],"a":1,"exp":"WSJF = Cost of Delay / Job Duration. A short project delivering $500K/month delay cost scores higher than a long project with the same delay cost. WSJF prevents organizations from always working on the biggest projects (which have the longest durations) while high-value quick wins sit in the queue. Used extensively in SAFe portfolio management.","competency":"pm:portfolio"},
{"q":"A portfolio review board must balance spend between run (keeping the lights on), grow (incremental business improvement), and transform (strategic change) investments. The current portfolio is 80% run. What should the board consider?","opts":["80% run is always appropriate for mature organizations","Increase transform investment immediately regardless of capacity","Assess whether the current ratio reflects deliberate strategic choice or default drift — if the market is disrupting the current business model, under-investment in transform creates long-term strategic risk; the ratio should reflect organizational intent, not inertia","Eliminate run projects to free capacity for transform"],"a":2,"exp":"Run/Grow/Transform balance is a strategic portfolio decision, not an operational default. Organizations that drift to high run spend without deliberate choice often discover they have under-invested in the capabilities needed for future competitiveness. The board should set a target ratio based on strategic intent and explicitly evaluate whether the current allocation reflects it.","competency":"pm:portfolio"},
{"q":"What is a program interdependency register, and how does a program manager use it?","opts":["A list of project team members and their skills","A log of dependencies between projects within the program — documenting what each project needs from others, when it is needed, who owns the delivery, and the risk if the dependency is late — used to proactively manage cross-project scheduling risks","A financial register tracking shared program costs","A stakeholder register for program-level stakeholders"],"a":1,"exp":"In programs, the most common cause of project failure is an unmet dependency from another project. The interdependency register makes every cross-project dependency visible: Project A needs the API from Project B by Week 12 for Project A''s integration testing. The program manager monitors delivery of dependencies and escalates at-risk items before they become schedule failures.","competency":"pm:portfolio"},
{"q":"An OKR (Objectives and Key Results) framework cascades from organizational level to program level to project level. A project PM receives a key result: ''Reduce customer onboarding time from 7 days to 2 days.'' How should the PM translate this into project scope?","opts":["Accept the target as a schedule milestone only","The key result is the project outcome — the PM works backward from the target to identify the deliverables, process changes, and system capabilities required to achieve it, making the key result the Definition of Done for the project","Ask the portfolio manager to restate the key result as a feature list","Use the key result only for executive reporting"],"a":1,"exp":"OKR cascade connects strategic ambition to project delivery. The project PM must understand: what must be true for onboarding to take 2 days instead of 7? That analysis identifies scope: which processes must change, which systems must be integrated, which handoffs must be eliminated. The KR becomes the acceptance criterion — the project delivers value, not just features.","competency":"pm:portfolio"},
{"q":"A benefits realization plan is most useful at which point in a program lifecycle?","opts":["Only at program closure","Only during initiation, when the business case is approved","Throughout the program lifecycle: defined at initiation, updated at each phase gate, and measured at 6-month and 12-month intervals after program closure — benefits realization extends beyond delivery","Only when benefits are first measurable"],"a":2,"exp":"Benefits are realized after delivery, not during it. The benefits realization plan defines: what benefits are expected, how they will be measured, who is accountable, and when measurements will occur. Post-closure measurement (6 and 12 months) determines whether the program delivered its strategic value — without this, the business case cannot be validated.","competency":"pm:portfolio"},
{"q":"What is the difference between program governance and project governance?","opts":["They are the same — the same governance body applies to both","Program governance oversees strategic alignment, benefits realization, and cross-project coordination at the program level; project governance oversees delivery of specific project scope, schedule, and cost within the bounds set by program governance","Program governance is only needed for government projects","Project governance is more important than program governance in all cases"],"a":1,"exp":"Program governance focuses on: Is the program still aligned with strategy? Are cumulative benefits on track? Are cross-project dependencies being managed? Project governance focuses on: Is this specific project on schedule, within budget, and delivering the right scope? Both governance levels are required; conflating them creates either micromanagement or strategic drift.","competency":"pm:portfolio"},
{"q":"Resource capacity planning at portfolio level reveals demand of 250 Java developer days in Q3 but only 180 days available. What are the PM''s options?","opts":["Accept the overcommitment and rely on overtime","Defer 70 days of demand to Q4 by deprioritizing lower-value projects, hire or contract 70 additional days, reduce scope of lower-priority projects, or combine these options — with analysis of each option''s cost and strategic impact","Cancel the lowest-priority project entirely without analysis","Report the gap and take no action"],"a":1,"exp":"Portfolio resource gaps require deliberate governance decisions: defer (which projects?), hire (at what cost?), scope reduce (on which projects?), or blend. The PM presents options with cost-benefit analysis to the portfolio board. Silently overcommitting teams and relying on overtime produces burnout, quality degradation, and schedule failure across multiple projects simultaneously.","competency":"pm:portfolio"},
{"q":"What does earned benefits management mean in a program context?","opts":["Tracking financial cost savings from completed projects","Monitoring and reporting whether the benefits planned in the business case are actually being realized after delivery — including corrective action if actual benefits lag projections","Distributing financial rewards to the program team","Calculating the NPV of future program benefits"],"a":1,"exp":"Earned benefits management applies earned value thinking to benefits: Is the benefit realization rate tracking to plan? If onboarding time reduction was projected to be 50% complete by Month 6 and actual is 20%, why? Are benefit owners taking the required actions? The program manager owns benefit realization accountability, not just delivery accountability.","competency":"pm:portfolio"},
{"q":"What is the MSP (Managing Successful Programmes) framework''s definition of a ''blueprint''?","opts":["The project schedule for the program","A description of the future state the organization will be in after the program is complete — covering business operations, information systems, people skills, and infrastructure — used as the definition of success for the program","A technical architecture diagram","A financial model for the program business case"],"a":1,"exp":"The MSP blueprint describes the target operating model: what the organization will look like when the program is done. It defines: what business processes will operate, what systems will support them, what skills the workforce will have, and what infrastructure will exist. All projects within the program contribute to moving from the current state to the blueprint.","competency":"pm:portfolio"},
{"q":"AI portfolio analytics tools can analyze project performance data across the portfolio and flag at-risk projects. What is the most valuable use of this capability for a portfolio manager?","opts":["Replacing the portfolio review board with AI recommendations","Using AI-generated portfolio health dashboards to focus human review time on at-risk projects, identifying portfolio-level patterns (e.g., all ERP projects are running over budget), and detecting early warning signals that would take weeks to surface through manual reporting","Automating all portfolio decisions","Using AI to generate business cases for new projects"],"a":1,"exp":"AI portfolio analytics shifts the portfolio manager from data-gathering to analysis and decision-making. Automated dashboards identify the 20% of projects needing attention; portfolio-level pattern detection identifies systemic issues (all projects in one business unit underperforming may indicate a resource or leadership issue). Human judgment applies to root cause and response; AI handles the signal detection.","competency":"pm:portfolio"},
{"q":"When evaluating portfolio risk aggregation, why can''t you simply add individual project risk scores together?","opts":["You can add them — summing project risks gives the total portfolio risk","Project risks are often correlated: a common vendor failure or economic event can trigger multiple project risks simultaneously, making the combined portfolio risk larger than the sum of individual risks — and some risks offset each other, making the portfolio less risky than the sum","Risk scores use different scales across projects making addition meaningless","Portfolio risk is always lower than project risk because of diversification"],"a":1,"exp":"Portfolio risk aggregation requires correlation analysis. If three projects depend on the same vendor, a vendor failure is not three independent risks — it is one risk with three consequences. Ignoring correlation understates portfolio risk. Conversely, a portfolio with both inflationary-sensitive and deflationary-sensitive projects may have partially offsetting risks. Simple addition captures neither effect.","competency":"pm:portfolio"},
{"q":"What is the strategic alignment vs. financial return trade-off in portfolio prioritization?","opts":["Strategic alignment always wins — financial return is irrelevant in portfolio decisions","Financial return always wins — strategy is only for executives","The trade-off arises when a project with high strategic alignment (entering a new market) has a negative short-term NPV, while a project with high NPV (extending an existing product) has low strategic alignment — the portfolio board must decide how much financial return to sacrifice for strategic positioning, driven by the organization''s investment horizon","There is no trade-off — all strategic projects have positive NPV"],"a":2,"exp":"Portfolio governance must balance return and strategy. A board that only approves positive-NPV projects may under-invest in the strategic capabilities needed for 5-year competitiveness. A board that only funds strategic projects may sacrifice the near-term profitability that funds the transformation. Explicit discussion of the investment horizon and strategic vs. financial weighting prevents implicit default choices.","competency":"pm:portfolio"}
]'::jsonb);

-- ── MODULE 14: Digital & Technology Project Leadership ────────────────────────
SELECT pg_temp.fill_pm_exam_b(14, '[
{"q":"Your organization is migrating 50 applications to the cloud. Application A is a legacy system with no remaining business value. Application B is a custom-built system that can be moved with minimal change. Application C runs on specialized hardware incompatible with the target cloud. Which ''6 R'' strategy applies to each?","opts":["All three should be Refactored for cloud-native architecture","A: Retire, B: Rehost (lift and shift), C: Retain (keep on-premises until a replacement is available)","A: Replatform, B: Refactor, C: Repurchase","A: Retain, B: Repurchase, C: Retire"],"a":1,"exp":"The 6 Rs: Retire eliminates applications with no business value (sunk cost avoidance). Rehost (lift and shift) moves applications to cloud without modification — fastest, lowest risk for compatible systems. Retain keeps systems on-premises when cloud migration is not feasible or cost-effective. Matching the strategy to the application''s characteristics is the PM''s planning responsibility.","competency":"pm:tech-delivery"},
{"q":"Which DORA metric measures the time between a code change being committed and that change successfully running in production?","opts":["Deployment Frequency","Lead Time for Changes — the elapsed time from commit to production deployment; a key indicator of delivery pipeline efficiency","Mean Time to Restore (MTTR)","Change Failure Rate"],"a":1,"exp":"DORA''s four metrics: (1) Deployment Frequency (how often), (2) Lead Time for Changes (how fast from commit to production), (3) MTTR (how quickly incidents are resolved), (4) Change Failure Rate (what percentage of deployments cause incidents). Lead Time for Changes measures end-to-end pipeline efficiency — it catches bottlenecks in testing, approvals, or deployment gates.","competency":"pm:tech-delivery"},
{"q":"As a PM on a software delivery project, you are told the team is implementing a CI/CD pipeline. What is your primary responsibility in this context?","opts":["Write the pipeline configuration code","Review and approve every automated test result before deployment","Ensure pipeline metrics (deployment frequency, lead time, change failure rate) are established as project KPIs, that test environment availability is resourced, and that organizational approval gates integrate cleanly into the automated pipeline — removing organizational friction without bypassing governance","Replace manual QA testers with the pipeline"],"a":2,"exp":"The PM does not build CI/CD pipelines — engineers do. The PM''s role: define success metrics for the pipeline, negotiate organizational gates that integrate into the automated flow (not manual stop-gaps that break automation), ensure test environment capacity, and communicate the pipeline''s value to non-technical stakeholders who may fear losing human control points.","competency":"pm:tech-delivery"},
{"q":"A development team tells you that a significant portion of sprint capacity is consumed by technical debt from earlier decisions. How should the PM treat technical debt in project planning?","opts":["Technical debt is a developer concern and outside the PM''s scope","Mandate that technical debt be eliminated before any new features are built","Document technical debt items in the risk register as project risk: quantify the capacity impact, negotiate a sustainable allocation (e.g., 20% of sprint capacity for debt reduction), communicate the trade-off to the sponsor, and include debt remediation in the project plan","Schedule a dedicated technical debt project after the current project ends"],"a":2,"exp":"Technical debt has measurable project impact: reduced velocity, increased defect rate, higher maintenance cost. The PM treats it as risk and negotiates a sustainable remediation allocation within each sprint. Framing technical debt as a risk — with quantified velocity impact — translates it into business language the sponsor can act on.","competency":"pm:tech-delivery"},
{"q":"Your data migration plan for a system cutover includes a rollback plan. What is the rollback plan''s most critical element?","opts":["The rollback plan is only needed if executives ask for one","The rollback decision trigger: at what specific point in the cutover process, if what specific conditions are met, will the team execute the rollback — and who has the authority to call it","A list of all data fields being migrated","The budget for the rollback effort"],"a":1,"exp":"The most common data migration failure is initiating rollback too late — after the point of no return, or after too much downstream data has been created in the new system. The rollback plan must define: the go/no-go decision point, specific technical and business criteria for triggering rollback, the decision-maker with authority to call it, and the execution steps. Without a defined trigger, teams delay the rollback decision under pressure.","competency":"pm:tech-delivery"},
{"q":"A cloud migration project must comply with GDPR. The project team is based in three countries. What is the PM''s responsibility regarding GDPR compliance?","opts":["GDPR compliance is a legal department responsibility — the PM has no role","Ensure GDPR compliance requirements are captured as functional and non-functional requirements in the project scope, that data privacy impact assessments (DPIAs) are scheduled as project milestones, that personal data flows are mapped as part of the architecture deliverable, and that a DPO review is a mandatory quality gate before go-live","Hire a GDPR consultant and delegate all compliance to them","Apply GDPR requirements only to European team members"],"a":1,"exp":"GDPR compliance is a project constraint — it shapes scope, architecture, testing, and timeline. The PM is responsible for integrating compliance into the project delivery process: capturing requirements, scheduling DPIAs, including DPO review gates, and ensuring the team understands which data types trigger GDPR obligations. Delegating it to legal without PM ownership creates compliance gaps.","competency":"pm:tech-delivery"},
{"q":"What is a hypercare period in a technology project deployment, and when does it end?","opts":["A period of reduced testing after go-live","The 2–4 week period immediately following go-live when enhanced support is provided: additional helpdesk staffing, vendor on-site support, accelerated incident resolution SLAs, and daily stabilization reviews — ending when incident rates return to normal levels and the system is stable","A pre-go-live testing phase","A contractual warranty period from the vendor"],"a":1,"exp":"Hypercare bridges the gap between deployment and normal operations. Go-lives generate high incident volume even in well-tested systems due to real-world data volumes and usage patterns not captured in testing. Hypercare ends on evidence (incident rate normalization), not on a fixed date — the PM must negotiate this with operations before cutover.","competency":"pm:tech-delivery"},
{"q":"What is vendor lock-in risk in a technology project, and how should a PM mitigate it?","opts":["The risk that a vendor will refuse to work with you in the future","The risk that dependency on a proprietary platform, API, or data format makes switching to an alternative prohibitively expensive — mitigated by requiring open standards, API portability clauses in contracts, data export rights, and technology strategy review at architecture decision points","The risk of the vendor going out of business","A compliance risk from using non-approved vendors"],"a":1,"exp":"Vendor lock-in is a long-term strategic risk that often feels invisible during delivery. Mitigation requires PM engagement in architecture decisions: advocate for open standards (open APIs, standard data formats), include data portability and exit rights in contracts, and ensure the architecture review evaluates switching cost alongside technical merit.","competency":"pm:tech-delivery"},
{"q":"The DevOps transformation team wants to move to continuous deployment with no change advisory board (CAB) approvals. The PM is responsible for regulatory compliance. How do you resolve the tension between DevOps speed and governance requirements?","opts":["Require CAB approval for every deployment — DevOps must adapt to existing governance","Eliminate all change approvals to enable true continuous deployment","Work with compliance, engineering, and risk stakeholders to define which change categories can be auto-approved (low-risk, fully automated pipeline with test gates) and which require lightweight CAB review (high-risk, regulated changes) — designing a tiered governance model that enables speed without abandoning compliance","Let the DevOps team decide — they understand the technical risk"],"a":2,"exp":"DevOps and governance are not inherently opposed. Tiered change approval: standard changes (pre-approved, fully automated with test gates) deploy without CAB; normal changes get lightweight async CAB review; emergency changes have expedited paths. Most organizations can achieve 80%+ auto-approval rates with proper pipeline instrumentation. The PM designs the governance model collaboratively.","competency":"pm:tech-delivery"},
{"q":"What does ''infrastructure as code'' (IaC) mean for a PM managing a cloud platform project?","opts":["The infrastructure team writes code instead of using GUI tools — this is a developer concern with no PM implications","IaC means infrastructure (servers, networks, databases) is defined in version-controlled code, enabling repeatable, auditable, and environment-consistent provisioning — for the PM this means: infrastructure changes go through the same change control as application code, environment setup is a codified deliverable, and environment consistency reduces the ''works in dev, fails in prod'' class of defects","IaC eliminates the need for infrastructure resources on the project","IaC means infrastructure procurement is no longer needed"],"a":1,"exp":"IaC has PM implications: (1) Infrastructure changes need code review and version control — include this in the change management process. (2) Environment provisioning is now a development task requiring code delivery — include it in the WBS. (3) IaC enables environment parity across dev/test/staging/production, reducing a major class of go-live defects that testing fails to catch.","competency":"pm:tech-delivery"},
{"q":"A PM is coordinating an MLOps delivery — the deployment of a machine learning model into a production system. What project governance elements are unique to ML model deployment versus standard software deployment?","opts":["ML model deployment is identical to software deployment — no additional governance is needed","ML model deployment requires additional governance: model performance monitoring (drift detection), model version control and rollback capability, bias and fairness testing as a quality gate, explainability documentation for regulated decisions, and data pipeline integrity validation — all of which the PM must incorporate as project deliverables and quality gates","MLOps is only relevant for AI companies, not mainstream project delivery","The data science team handles all MLOps governance independently"],"a":1,"exp":"ML models introduce unique risks: model drift (performance degrades as real-world data diverges from training data), bias in model outputs, and explainability requirements in regulated domains. The PM must include model monitoring as an ongoing deliverable, data pipeline validation as a quality gate, and rollback procedures if model performance degrades. Standard software testing does not catch these risks.","competency":"pm:tech-delivery"},
{"q":"You are a tech PM presenting to a business stakeholder who asks why the team cannot ''just add one small database field'' quickly. The team estimates 3 days. How do you explain the complexity?","opts":["Tell the stakeholder the team is being inefficient","Agree to do it in 1 day to meet the stakeholder''s expectation","Translate the technical complexity: adding a field requires schema migration, backward compatibility validation, API changes, test updates, documentation changes, and deployment across environments — 3 days reflects due diligence, not inefficiency. Frame this as protecting production quality rather than the team being slow","Escalate the misalignment to the sponsor"],"a":2,"exp":"The tech PM''s critical role is stakeholder translation — converting technical complexity into business-language rationale. Stakeholders who understand why 3 days is the right answer become allies; stakeholders left with ''it takes 3 days'' become adversaries who push for shortcuts. The PM bridges the technical-business communication gap.","competency":"pm:tech-delivery"},
{"q":"What is zero-downtime deployment, and what does the PM need to plan for to enable it?","opts":["Deploying only during weekends to minimize user impact","A deployment strategy where the new version is released without any service interruption — enabled by blue/green deployment, canary releases, or rolling updates — requiring the PM to plan for feature flagging capability, database migration compatibility, and load balancer configuration as project deliverables","A deployment approach that eliminates testing to save time","A deployment process that requires no team involvement"],"a":1,"exp":"Zero-downtime deployment requires architectural and operational prerequisites: (1) blue/green or canary deployment infrastructure, (2) database changes that are backward compatible (so old and new code run simultaneously), (3) feature flags to decouple deployment from release. The PM plans these as technical deliverables — they cannot be retrofitted at deployment time.","competency":"pm:tech-delivery"},
{"q":"Your organization has been running a legacy CRM on-premises for 12 years. The replacement SaaS CRM project includes decommissioning the old system. What is the PM''s key risk in the decommission phase?","opts":["The new system may be too expensive","Staff may prefer the old system","Historical data in the legacy system needed for regulatory compliance, audit, or operational reporting may not have been fully migrated or archived — decommissioning too early creates irreversible data loss risk","The vendor of the old system may object to decommissioning"],"a":2,"exp":"Legacy decommission risk: data completeness. Twelve years of transactional data may have compliance retention requirements (7-year audit trail, for example). The PM must: complete a data inventory, validate migration completeness against the inventory, archive all retention-required data in an accessible format, and obtain formal sign-off from legal, finance, and compliance before decommission — not just from the technology team.","competency":"pm:tech-delivery"},
{"q":"What DORA metric directly measures the reliability and resilience of a technology delivery team''s production system?","opts":["Deployment Frequency","Lead Time for Changes","Change Failure Rate — the percentage of deployments that cause a service degradation or outage, directly measuring the quality of the delivery process and the stability of production","Mean Time to Restore (MTTR)"],"a":2,"exp":"Change Failure Rate measures how often the team''s deployments break production. A high rate indicates: insufficient testing, poor change management, or inadequate deployment processes. Elite teams (per DORA research) have change failure rates below 5%. The PM tracks this alongside deployment frequency — high frequency with high failure rate is worse than low frequency with low failure rate.","competency":"pm:tech-delivery"}
]'::jsonb);

-- ── MODULE 15: Data-Driven PM & Analytics ─────────────────────────────────────
SELECT pg_temp.fill_pm_exam_b(15, '[
{"q":"Your project status dashboard shows: Schedule Performance Index (SPI) = 0.88, Cost Performance Index (CPI) = 0.92, and 3 pending scope change requests. What RAG status should you assign, and why?","opts":["Green — both indices are above 0.80","Red — any index below 1.0 is a Red status","Amber — both indices indicate underperformance but not critical levels; you have pending scope changes that could worsen performance; the trend matters more than a single data point — investigate before escalating to Red","Green — only Red is appropriate if the project will miss its deadline"],"a":2,"exp":"RAG thresholds should be pre-defined in the project management plan, but typical convention: CPI/SPI 0.85–0.95 = Amber (corrective action needed but not yet critical). Below 0.85 = Red. Three pending scope changes create additional uncertainty. The PM assigns Amber, communicates the trend, and presents a corrective action plan.","competency":"pm:analytics"},
{"q":"What is the difference between leading and lagging indicators in project reporting?","opts":["Leading indicators are more accurate than lagging indicators","Leading indicators predict future project outcomes (e.g., number of open defects 4 weeks before go-live, sprint velocity trend, team overtime hours); lagging indicators measure what already happened (e.g., defect escape rate, schedule variance) — leading indicators enable proactive management","Lagging indicators are used in Agile; leading indicators are used in waterfall","There is no meaningful difference — both measure the same outcomes"],"a":1,"exp":"Lagging indicators measure outcomes that are already fixed (you cannot change last month''s cost variance). Leading indicators measure conditions that predict future outcomes — high open defect count 4 weeks before go-live predicts a troubled release. PMs who track only lagging indicators manage in the rearview mirror; leading indicators enable course correction.","competency":"pm:analytics"},
{"q":"An S-curve on your project shows that actual costs are tracking above the baseline cost curve from Week 6 onward, while earned value is tracking below the baseline. What does this pattern indicate?","opts":["The project is ahead of schedule and under budget","The project is spending more than planned and delivering less value than planned — a double-negative: both CPI and SPI are below 1.0, indicating cost overrun and schedule delay simultaneously","The project is over budget but ahead of schedule","The S-curve data is inconclusive without more information"],"a":1,"exp":"S-curve reading: if Actual Cost (AC) tracks above the baseline and Earned Value (EV) tracks below, you are in the worst quadrant — spending faster than planned while delivering slower than planned. CPI < 1.0 (AC > EV) and SPI < 1.0 (EV < PV). This requires immediate escalation and corrective action, not just monitoring.","competency":"pm:analytics"},
{"q":"What is regression to the mean in the context of project forecasting, and why does it matter?","opts":["A statistical term for projects that return to the original baseline","The tendency for extreme early-project performance (very good or very bad) to moderate toward average performance over time — early over-performance often does not persist; early under-performance sometimes self-corrects — PMs should not over-react to early data points or assume trends will continue indefinitely","A technique for correcting schedule variance","A method for adjusting estimates using historical data"],"a":1,"exp":"A project with SPI=1.15 in Week 2 may be benefiting from early favorable conditions that will not persist. Assuming the performance continues leads to over-optimistic forecasts. Conversely, a Week 2 SPI of 0.85 may be due to startup delays that self-correct. PMs should require several data points before treating a performance trend as indicative of the project''s trajectory.","competency":"pm:analytics"},
{"q":"A pre-mortem technique is used before project completion. What is its purpose, and why is it more effective than a post-mortem?","opts":["A pre-mortem reviews lessons learned from previous projects","A pre-mortem asks the team to imagine the project has already failed and work backward to identify what most likely caused the failure — surfacing risks that normal forward-planning misses while there is still time to prevent them; post-mortems surface learnings after failure, when it is too late to prevent it","A pre-mortem is used to assess team performance before project closure","Pre-mortems are less effective than post-mortems because they are hypothetical"],"a":1,"exp":"Pre-mortem: ''It is 6 months from now. The project failed spectacularly. What happened?'' This framing overcomes optimism bias — people are better at generating failure scenarios when asked to imagine failure as a fact. Risks surfaced in a pre-mortem can be mitigated proactively. Post-mortem learnings benefit future projects, not the one that just failed.","competency":"pm:analytics"},
{"q":"Your weekly report shows budget variance of −$5,000 this week, −$2,000 last week, and −$500 three weeks ago. What is the most important analytical insight from this trend?","opts":["The project is slightly over budget — within acceptable tolerance","The budget variance is accelerating: overspend is growing each week, not stabilizing — the trend predicts a significant overrun if the root cause is not addressed; the absolute value is less important than the direction and rate of change","The variance is not statistically significant at this scale","Weekly variance fluctuations are normal and no action is needed"],"a":1,"exp":"Trend analysis is more informative than point-in-time data. A variance of −$5,000 sounds manageable; a variance that tripled in 3 weeks signals an accelerating cost driver. The PM must identify the root cause (scope added without cost baseline update? Resource rate variance?) and act on the trend, not just accept the current value.","competency":"pm:analytics"},
{"q":"What is the RAPID decision framework, and how does a PM apply it to clarify decision-making on complex projects?","opts":["A risk assessment process (Risk, Action, Priority, Impact, Decision)","A decision rights framework defining who: Recommends options, Agrees (must consent), Performs execution, Inputs data, and Decides — used to clarify who makes decisions and who influences them, preventing decision paralysis and committee-based delays","A project approval framework for portfolio decisions","A communication model for executive reporting"],"a":1,"exp":"RAPID (Recommend, Agree, Perform, Input, Decide) prevents the most common project governance failure: unclear decision rights. When everyone thinks they have veto power, decisions stall. When nobody knows who decides, accountability evaporates. The PM applies RAPID at project start to map each major decision type to the right role.","competency":"pm:analytics"},
{"q":"A marketing campaign costs $200,000. There is a 60% chance it increases revenue by $500,000 and a 40% chance it delivers no revenue increase. What is the net Expected Monetary Value (EMV) of running the campaign?","opts":["$300,000 — the expected revenue increase","$100,000 — calculated as (0.60 × $500,000) + (0.40 × $0) − $200,000 campaign cost","$200,000 — the campaign cost","$500,000 — the maximum possible revenue increase"],"a":1,"exp":"EMV: (0.60 × $500,000) + (0.40 × $0) = $300,000 expected revenue − $200,000 cost = $100,000 net EMV. A positive net EMV supports running the campaign. Decision trees with EMV calculation enable PMs and sponsors to make investment decisions based on probability-weighted outcomes rather than best-case or worst-case scenarios alone.","competency":"pm:analytics"},
{"q":"What is confirmation bias in PM reporting, and how does it affect project outcomes?","opts":["A statistical error in forecasting models","The tendency for PMs to selectively present or interpret data that confirms the project is on track, while downplaying or ignoring data that suggests problems — leading to delayed escalation and missed opportunities for early corrective action","A type of stakeholder resistance to project metrics","A bias in AI forecasting algorithms"],"a":1,"exp":"Confirmation bias in PM reporting is one of the most dangerous cognitive traps: the PM reports Green because the positive signals are visible and the negative signals are rationalized away. Senior stakeholders receive a distorted picture and cannot make good decisions. Rigorous PM practice requires presenting all significant data, especially contradicting signals, and letting the governance body draw conclusions.","competency":"pm:analytics"},
{"q":"A stakeholder suggests tracking 25 metrics on your project dashboard. Why is this problematic, and what is the correct KPI selection principle?","opts":["25 metrics is fine — more data is always better for decision-making","25 metrics creates signal noise: decision-makers cannot identify what requires attention when everything is measured; apply SMART criteria and select 5–8 metrics — each metric should trigger a specific decision or action if it breaches its threshold","Track all 25 metrics but only report 5 to executives","Metrics selection is a PMO standard that the PM cannot influence"],"a":1,"exp":"Dashboard design principle: a metric that does not trigger a decision is noise. 25 metrics on a single dashboard creates cognitive overload — the critical signals are buried. Best practice: 5–8 metrics maximum for executive dashboards, each with a defined threshold that triggers a specific management action. More detail is available on drill-down; the dashboard shows signals, not data.","competency":"pm:analytics"},
{"q":"What does a cumulative flow diagram (CFD) with constant horizontal bands across all stages indicate about the delivery system?","opts":["The team is over-committed and needs more resources","A stable, predictable flow with consistent WIP levels across all stages — this is the ideal state for a Kanban or flow-based delivery system, indicating work is moving through stages at a steady rate without accumulating in any one stage","The team is not accepting new work","The CFD data is not being updated correctly"],"a":1,"exp":"Constant-width bands in a CFD indicate stable WIP and consistent throughput — the system is in flow. The PM uses this as the health indicator: bands that widen indicate WIP accumulation (bottleneck); bands that narrow indicate starvation (insufficient input). A smooth CFD is the visual signature of a well-managed flow system.","competency":"pm:analytics"},
{"q":"What is the difference between throughput and velocity as Agile delivery metrics, and when is each most useful?","opts":["They are the same metric measured in different units","Velocity (story points completed per sprint) measures the amount of work a Scrum team completes using relative sizing; throughput (number of items completed per time period) measures flow in Kanban without requiring sizing — throughput is more useful when story point estimation is inconsistent or teams want to eliminate estimation overhead","Throughput is only relevant for manufacturing, not software","Velocity is more accurate because it accounts for story complexity"],"a":1,"exp":"Velocity requires story point estimation; throughput does not (it counts completed items). Throughput is more reliable when estimation quality is low or inconsistent. For forecasting, ''if we complete 12 items per week and have 60 items left, we need about 5 weeks'' is simpler and often as accurate as velocity-based forecasting. Teams transitioning away from estimation often use throughput.","competency":"pm:analytics"},
{"q":"An AI anomaly detection system alerts you that task completion reporting has shifted to predominantly Friday afternoons over the last 3 weeks. What does this pattern suggest?","opts":["The team is becoming more productive on Fridays","The team may be managing to perceptions: waiting to mark tasks complete until just before the weekly status report is due, potentially masking real schedule problems — the PM should investigate whether task statuses are being updated accurately or managed to create a false picture of progress","This is a normal working pattern with no significance","The sprint planning is creating Friday-heavy task assignments"],"a":1,"exp":"Friday-clustering of task completions is a classic gaming signal in earned value tracking. If work is genuinely completing throughout the week but being reported on Friday for ''convenience,'' it creates false schedule health signals. If work is actually completing late and being reported on-time to make the Friday report look good, it masks schedule risk. The PM investigates by comparing task completion patterns to actual team output.","competency":"pm:analytics"},
{"q":"What are data-driven escalation triggers, and why are they more effective than PM judgment alone for escalation decisions?","opts":["Escalation triggers are only needed for large programs","Data-driven triggers are pre-defined, objective thresholds that automatically require PM escalation (e.g., CPI < 0.85 for two consecutive weeks, schedule variance > 3 weeks, 3 or more critical path tasks delayed simultaneously) — they remove ambiguity about when to escalate and prevent PMs from delaying bad news due to optimism or discomfort","Escalation should always be based on PM judgment only","Triggers are set by the sponsor, not the PM"],"a":1,"exp":"Pre-defined escalation triggers solve the PM''s most common failure mode: late escalation driven by ''I thought I could fix it'' optimism. When triggers are objective and pre-agreed, the PM has no discretion to delay bad news — the data dictates escalation. This also protects the PM: ''I escalated when the CPI hit 0.84 as defined in the project management plan'' is defensible; ''I decided it was not serious enough'' is not.","competency":"pm:analytics"},
{"q":"A project sponsor asks for a ''single number'' to summarize project health. Why is a single metric insufficient, and what is the minimum set of dimensions needed for an accurate project health picture?","opts":["A single metric is sufficient — overall RAG status captures everything","Schedule variance alone is the best single metric","No single metric captures multi-dimensional project health: a minimum picture requires schedule performance (SPI), cost performance (CPI), scope stability (pending change requests and approved changes), risk trend (open high-risk items), and quality indicators (defect rate) — together they prevent the ''looks fine in one dimension, failing in another'' blind spot","The sponsor is correct — simplify to one number for executive communication"],"a":2,"exp":"Single-metric health assessment creates dangerous blind spots. A project can be on schedule (SPI=1.0) but massively over budget (CPI=0.70). A project can be under budget (CPI=1.10) because it has not done the work yet (SPI=0.65). The minimum health dashboard covers: schedule, cost, scope, risk, and quality — five dimensions that together describe whether the project is truly healthy.","competency":"pm:analytics"}
]'::jsonb);

-- ── MODULE 16: Executive Communication & Strategic Leadership ─────────────────
SELECT pg_temp.fill_pm_exam_b(16, '[
{"q":"You need to brief a C-suite executive on a project that has shifted from Green to Red status. You have 10 minutes. What structure should your briefing follow?","opts":["Start with detailed background on the project history","Lead with technical root cause analysis","Use BLUF (Bottom Line Up Front): open with the current status and what it means for the business, then state the specific problem, the options and your recommendation, and what decision you need from the executive — keeping all detail in a written appendix","Present all data first and let the executive draw their own conclusions"],"a":2,"exp":"BLUF is the executive communication standard. Executives make many decisions daily with limited time. Opening with the bottom line (''This project is now Red; without an additional $150K, we will miss the December deadline'') respects their time and frames what follows. Detail is available but not imposed. Executives who must listen to background before hearing the point disengage.","competency":"pm:executive-comms"},
{"q":"What is a one-page project status brief, and what are its five essential components?","opts":["A detailed project schedule summarized on one page","A one-page executive communication tool containing: (1) project name and reporting period, (2) RAG status with threshold justification, (3) key accomplishments this period, (4) key activities next period, (5) decisions or escalations required — designed to be read in under 2 minutes","A summary of all risks and issues","A financial report showing budget versus actuals"],"a":1,"exp":"The one-pager disciplines PM communication: if you cannot fit the project status on one page in executive-readable format, you have not finished thinking about what matters most. The five components answer the executive''s questions: Are we okay? What happened? What''s next? What do I need to do? One-pagers compound: a year of one-pagers creates a complete project narrative.","competency":"pm:executive-comms"},
{"q":"You need to give a 3-minute verbal project update at an executive leadership team meeting. What structure maximizes effectiveness?","opts":["Spend 2 minutes on background and 1 minute on current status","Start with detailed metrics and let the executive ask questions","30 seconds: current RAG status and one-line project purpose. 90 seconds: key accomplishments, major risks, and trend. 60 seconds: one specific request or decision needed. End on time — do not fill unused time","Begin with a comprehensive risk register review"],"a":2,"exp":"3-minute verbal updates must be ruthlessly prioritized. Purpose (why this project matters) orients listeners who may not track every project. RAG and trend communicate health. The specific request is the most important element — executives in the room have the authority to unblock; the PM must use the time to make the ask clearly and specifically.","competency":"pm:executive-comms"},
{"q":"You have identified the CFO as a key stakeholder who has the power to derail your project''s funding but is currently neutral. What is power mapping, and how would you use it?","opts":["Power mapping is a financial analysis tool","Power mapping analyzes the relationships, influence chains, and motivations of stakeholders — identifying who influences the CFO, what her primary business concern is, which of her allies support the project, and how to engage her through the right channel with the right message to move her from neutral to supportive","Power mapping is only used in political science, not project management","Power mapping means documenting all stakeholders with high formal authority"],"a":1,"exp":"Power mapping goes beyond the power/interest grid: it traces influence networks. The CFO may be influenced by the COO, who is project-positive. Her primary concern may be ROI timeline, not total cost. Engaging through a trusted channel (COO ally) with her specific concern (ROI evidence) is more effective than a direct cost-focused briefing. Map before engaging.","competency":"pm:executive-comms"},
{"q":"You are in a negotiation with a vendor demanding a $200,000 contract extension. You have budget for $150,000. What is BATNA, and how does knowing it change your negotiation position?","opts":["BATNA is a negotiation technique for avoiding conflict","BATNA (Best Alternative to a Negotiated Agreement) is what you will do if the negotiation fails — in this case, your next-best vendor alternative. Knowing your BATNA and the vendor''s BATNA establishes your respective walk-away points and gives you the confidence to hold the $150,000 position if the alternative is genuinely competitive","BATNA is the average of the two negotiating positions ($175,000)","BATNA means you should always accept the vendor''s opening position to maintain the relationship"],"a":1,"exp":"BATNA is the foundation of principled negotiation. Knowing your alternative (another vendor at $145,000) gives you genuine walk-away power. Knowing the vendor''s alternative (no other client for this capacity) tells you how far they can be pushed. The ZOPA (Zone of Possible Agreement) is between your walk-away point and theirs. Without BATNA analysis, you negotiate from assumed position, not actual power.","competency":"pm:executive-comms"},
{"q":"A project you are managing is in crisis: go-live is 6 weeks away, 30% of UAT has failed, and two key developers have resigned. What is the project recovery triage sequence?","opts":["Immediately extend the go-live date and request additional budget","Triage (assess the true current state honestly — what exactly is failing and why), Stabilize (stop the bleeding — prevent further deterioration), Reset (renegotiate the scope, schedule, or resources with sponsor alignment), Rebuild (execute the revised plan) — in this sequence, because stabilizing before understanding the problem applies the wrong fixes","Immediately escalate to the board without a recovery plan","Replace the two developers before assessing the testing failures"],"a":1,"exp":"Project recovery follows a structured sequence: Triage first — a clear-eyed assessment of what is actually wrong prevents applying the wrong fix. Stabilize — prevent further deterioration while you plan. Reset — engage the sponsor with an honest assessment and renegotiated parameters. Rebuild — execute the revised plan. Organizations that skip Triage and jump to Reset often reset to an equally flawed plan.","competency":"pm:executive-comms"},
{"q":"You are presenting a project delay to executives who were expecting an on-time delivery. What crisis communication principles should guide your approach?","opts":["Minimize the severity of the delay to reduce stakeholder anxiety","Present only the positive aspects of the project to balance the bad news","Lead with factual, complete disclosure of the delay and its cause; demonstrate that you understand the business impact; present a specific, concrete recovery plan; own the situation without making excuses; and provide a revised commitment with the evidence behind it","Wait until you have a full recovery plan before communicating the delay"],"a":2,"exp":"Crisis communication principles: (1) Disclose fully and factually — partial disclosure destroys trust when the full picture emerges. (2) Demonstrate business impact understanding — executives care about impact, not technical cause. (3) Own the situation — explaining without excusing. (4) Present a specific recovery plan with evidence. (5) Give a revised commitment you can keep. Late disclosure is always worse than early disclosure.","competency":"pm:executive-comms"},
{"q":"What is Cialdini''s principle of reciprocity as applied to influencing without authority in a project context?","opts":["If you give stakeholders what they want, they will approve your project changes","Reciprocity means stakeholders will feel an obligation to support your project if you have genuinely helped them first — helping a stakeholder solve a problem, sharing useful information, or advocating for their priorities creates social capital that you can draw on when you need their cooperation","Reciprocity is a manipulation technique that damages trust","Reciprocity only applies to financial incentives"],"a":1,"exp":"Cialdini''s reciprocity: people feel compelled to return favors. PMs who help stakeholders (resolve their team''s issues, share project learnings that benefit them, advocate for their priorities) build genuine relationship credit. When the PM later needs the stakeholder''s cooperation on a difficult request, the accumulated credit enables influence that formal authority cannot create.","competency":"pm:executive-comms"},
{"q":"What is the difference between reporting to executives and communicating with executives?","opts":["There is no meaningful difference — both involve sharing project information","Reporting delivers data (on schedule, under budget); communicating drives decisions and action — a PM who only reports gives executives information; a PM who communicates frames the information as decisions, options, and recommendations that leverage executive authority to advance the project","Reporting is written; communicating is verbal","Executives prefer reporting over communication"],"a":1,"exp":"PMs who only report abdicate their strategic leadership role. Executives have authority to remove barriers, approve additional funding, resolve cross-organizational conflicts, and prioritize the project above competing demands. The PM''s job is to frame information as decisions: ''You have three options: approve $50K for additional resources, reduce scope by 15%, or accept a 3-week delay. I recommend option 1 because...'' This drives action; a status report does not.","competency":"pm:executive-comms"},
{"q":"Coalition building is an influence strategy for large transformational projects. What does it involve?","opts":["Forming an alliance of senior executives who all report to the same leader","Building a cross-organizational network of stakeholders who each individually support the project and who collectively create the organizational momentum necessary to overcome resistance — by identifying natural allies, understanding their motivations, aligning project benefits to their priorities, and coordinating their advocacy","A legal structure for multi-organizational projects","A vendor consortium for large procurement projects"],"a":1,"exp":"Coalition building is essential for transformational projects that cut across multiple organizational units. No single sponsor can overcome all resistance. A coalition: CFO who sees cost savings, COO who sees operational improvement, and CHRO who sees talent development value — each advocating from their domain creates cross-organizational momentum. The PM identifies, recruits, and coordinates the coalition.","competency":"pm:executive-comms"},
{"q":"Your project sponsor is not providing decisions needed for the project to proceed. Three decisions have been pending for 2 weeks. What is the most effective approach to managing up?","opts":["Escalate to the sponsor''s manager immediately","Accept the delays as part of organizational reality","Reframe the pending decisions as time-sensitive business risks with quantified consequence of delay, present options with a clear recommendation, and request a 15-minute decision meeting with a specific date — making the decision easy for the sponsor","Send daily email reminders until the sponsor responds"],"a":2,"exp":"Managing up effectively requires reframing: sponsors do not delay decisions out of malice — they are busy. The PM''s job is to make the decision easy: quantify the cost of delay, present pre-analyzed options with a recommendation, and request a specific short meeting. A sponsor who sees ''3 options, I recommend option 2, need 15 minutes by Thursday'' is far more likely to act than one receiving ''we need your decision on items 3.1, 3.2, and 3.3.''","competency":"pm:executive-comms"},
{"q":"What is executive presence for a PM, and how is it demonstrated in practice?","opts":["Being the most technically knowledgeable person in the room","Executive presence is the combination of credibility (you know your project and its business context), communication clarity (you can synthesize complex situations into actionable insights), composure (you remain steady under pressure), and confidence (you provide recommendations, not just options) — demonstrated through preparation, succinctness, and willingness to take a position","Having a senior title or years of experience","Avoiding disagreement with executive stakeholders"],"a":1,"exp":"PMs with executive presence are trusted advisors, not just status reporters. They demonstrate: mastery of their project details, ability to connect project outcomes to business strategy, calm composure when presenting bad news, and the confidence to say ''my recommendation is X'' rather than ''here are three options, you decide.'' Executive presence is earned through consistent credibility, not seniority.","competency":"pm:executive-comms"},
{"q":"Political intelligence in project management means:","opts":["Participating in office politics to advance personal career goals","Understanding the organizational landscape — who has formal and informal power, what the unspoken organizational priorities are, where tensions between stakeholders exist, and how decisions actually get made (formally and informally) — and navigating this landscape effectively to advance the project","Avoiding all organizational politics to maintain neutrality","Reporting political conflicts to HR"],"a":1,"exp":"Political intelligence is a PM competency, not a character flaw. Organizations run on formal structures and informal influence networks simultaneously. A PM who understands that the CFO and COO have competing priorities, that the real decision on IT projects happens in a Tuesday morning call, and that a specific executive has informal veto power navigates far more effectively than one who assumes the org chart reflects actual influence.","competency":"pm:executive-comms"},
{"q":"A senior stakeholder is resisting the project''s recommendation at the executive level but has not stated a specific objection. What is the most effective PM response?","opts":["Present more data in the next steering committee to overcome their resistance","Escalate to the CEO to force a decision","Request a private one-on-one meeting with the stakeholder to understand their unstated concern — asking open-ended questions about their perspective, listening without defending, and identifying whether the resistance is about the project, its impact on their domain, or a relationship or political factor that requires a different response","Ignore the resistance and proceed to implementation"],"a":2,"exp":"Unstated resistance is the most dangerous stakeholder challenge — it cannot be addressed until it is understood. A private conversation outside the committee forum creates safety for the stakeholder to articulate the real concern: ''I''m worried this will disrupt my team during year-end,'' or ''I was not consulted during the design phase.'' Each real concern has a specific resolution; generic resistance does not.","competency":"pm:executive-comms"},
{"q":"What is thought leadership in the context of PM career development, and how does it differ from technical expertise?","opts":["Thought leadership means having the most certifications","Technical expertise is depth in PM tools and techniques; thought leadership is the ability to articulate a perspective on where the profession, industry, or technology is heading — demonstrated through writing, speaking, mentoring, or community contribution — creating visibility and credibility beyond the boundaries of your current organization","Thought leadership is only relevant for consultants","Thought leadership requires a published book"],"a":1,"exp":"Technical expertise makes you valuable in your current role; thought leadership makes you visible and influential beyond it. A PM who writes about AI in delivery, speaks at PMI chapters, mentors junior PMs, or contributes to professional communities demonstrates judgment and perspective — qualities that senior roles (program director, PMO leader, VP delivery) require but that competent execution alone does not demonstrate.","competency":"pm:executive-comms"}
]'::jsonb);

-- ── MODULE 17: Ethics, Governance & AI Responsibility ────────────────────────
SELECT pg_temp.fill_pm_exam_b(17, '[
{"q":"Your organization''s PMO is classified as ''directive'': it mandates specific methodologies, provides project managers for projects, and enforces compliance with standards. A business unit wants to use a different delivery methodology because their projects are highly innovative. How should the PM navigate this?","opts":["Mandate the standard methodology regardless of project characteristics","Ignore the PMO directive and use the preferred methodology","Work within the directive PMO framework: document the business case for a tailored approach, escalate through PMO governance channels to request a formal methodology exception, and propose how the tailored approach will still meet core governance requirements","Ask the team to use the approved methodology in reporting but operate differently in practice"],"a":2,"exp":"Directive PMOs enforce standards for compliance and consistency reasons. Circumventing them undermines governance. The PM''s professional obligation is to work within the governance structure while advocating for change through legitimate channels: document why the standard approach is inappropriate, propose a tailored approach that meets governance objectives, and request a formal exception through the PMO. Covert non-compliance is never acceptable.","competency":"pm:governance"},
{"q":"A steering committee charter should define all of the following EXCEPT:","opts":["The committee''s authority and decision rights","Meeting cadence and quorum requirements","Membership and role responsibilities","The detailed project schedule and task assignments for the project team"],"a":3,"exp":"The steering committee charter is a governance document: it defines the committee''s authority, composition, cadence, decision thresholds, and escalation criteria. Detailed project task assignments belong in the project management plan, not the governance charter. Including operational project detail in a governance charter confuses strategic oversight with operational management.","competency":"pm:governance"},
{"q":"A decision rights matrix using DACI (Driver, Approver, Contributor, Informed) differs from RACI in what key way?","opts":["DACI and RACI are identical frameworks with different acronyms","DACI explicitly distinguishes between the Driver (coordinates the decision process), Approver (has final decision authority — only one), Contributors (provide input), and Informed (notified) — emphasizing that decisions have a single Approver and a process Driver, whereas RACI focuses on work delivery accountability rather than decision governance","DACI is used for Agile projects; RACI is for waterfall","DACI allows multiple Approvers; RACI requires one"],"a":1,"exp":"RACI governs work delivery (who does the work, who owns the outcome). DACI governs decision-making (who drives the process, who has final authority). DACI is particularly useful for cross-functional decisions where multiple stakeholders want veto power. Explicitly naming one Approver prevents the ''design by committee'' trap.","competency":"pm:governance"},
{"q":"GDPR Article 25 requires ''privacy by design'' as a project constraint. What does this mean for the PM''s project plan?","opts":["Privacy by design means adding a data privacy review at the end of the project","Privacy by design requires that data protection principles are embedded from the start of the system design, not retrofitted: the PM must include privacy impact assessment milestones, data minimization requirements in the scope statement, security architecture review gates, and DPO sign-off as a go/no-go condition for go-live","Privacy by design is a vendor responsibility in outsourced projects","GDPR only applies to projects in the European Union and has no relevance to project management"],"a":1,"exp":"Article 25 makes privacy a design requirement, not an audit check. For the PM: privacy requirements belong in the scope statement from day one; DPIAs are project milestones; the technical architecture must demonstrate data minimization and purpose limitation. A system built without privacy by design will require expensive redesign to achieve GDPR compliance.","competency":"pm:governance"},
{"q":"Your project uses an AI tool to prioritize the backlog and allocate resources. An analyst notices that the AI consistently de-prioritizes work from Team B, and Team B is composed predominantly of employees from a minority group. What is the PM''s responsibility?","opts":["The AI tool''s decisions are objective and cannot be biased","Report the finding only if Team B members formally complain","Immediately pause the AI tool''s output for resource allocation decisions, investigate the training data and algorithmic logic for bias, engage your data science and HR teams, conduct a manual audit of past allocation decisions, and document your investigation — you cannot deploy an AI tool with demonstrated discriminatory effects","Ask the AI tool to re-run its allocation with a different configuration"],"a":2,"exp":"Algorithmic bias in resource allocation is both an ethical issue and a legal risk (discrimination law). The PM is accountable for outputs produced under their project governance, including AI-generated outputs. Pause, investigate, document, and remediate before re-enabling. ''The algorithm decided'' is not an acceptable defense for discriminatory project outcomes.","competency":"pm:governance"},
{"q":"What is the PM''s responsibility for validating AI output on a project that uses AI-generated risk assessments?","opts":["AI risk assessments are more accurate than human judgment and require no validation","The PM is responsible for treating AI risk assessment outputs as one input requiring human validation: cross-checking AI-identified risks against domain expert knowledge, verifying the AI''s assumptions are consistent with the current project context, and maintaining documentation that human oversight was applied before acting on AI recommendations","The AI vendor is responsible for the accuracy of AI risk outputs","AI outputs should be accepted without review to avoid introducing human bias"],"a":1,"exp":"AI outputs are probabilistic estimates, not authoritative facts. The PM''s responsibility: AI risk identification is a starting point for the risk register, not a substitute for expert risk workshops. AI may miss novel risks without historical precedent. The PM documents that human validation occurred — this is both good practice and, in regulated industries, often a compliance requirement.","competency":"pm:governance"},
{"q":"ESG (Environmental, Social, Governance) screening criteria are increasingly applied to project approval decisions. Which question would an ESG-aligned portfolio board ask when reviewing a proposed data center project?","opts":["What is the project''s 5-year ROI?","What are the project''s scope and schedule?","What is the estimated carbon footprint of the data center, what renewable energy commitments are included, what is the impact on local employment, and what data governance policies will prevent regulatory compliance risk?","Who is the project manager and what is their experience?"],"a":2,"exp":"ESG screening applies environmental (carbon impact, energy sourcing), social (community impact, labor standards, supply chain ethics), and governance (data policies, regulatory compliance, board accountability) lenses to investment decisions. ESG-aligned portfolio boards require PMs to quantify and disclose these dimensions alongside financial returns.","competency":"pm:governance"},
{"q":"A PM discovers that a subcontractor on the project is engaging in practices that appear to violate local labor laws. The subcontractor is not in the PM''s direct contract — they are engaged by the prime vendor. What is the PM''s obligation?","opts":["The PM has no obligation — this is the prime vendor''s issue","Document the observation and raise it at the next quarterly vendor review","Escalate immediately through the PM''s internal compliance and legal channels, document the observation in writing, and require the prime vendor to address the subcontractor practices — the PM''s organization bears reputational and potentially legal risk from supply chain practices, regardless of contractual indirectness","Ask the subcontractor directly to correct the practices without involving legal"],"a":2,"exp":"Supply chain compliance extends beyond direct contracts. PMI''s Code of Ethics requires PMs to act responsibly in their sphere of influence. Labor law violations by subcontractors create reputational, legal, and ESG risk for the buying organization. Immediate escalation through legal and compliance channels protects both the organization and the affected workers.","competency":"pm:governance"},
{"q":"What is carbon-aware scheduling in the context of technology project delivery, and why is it a PM consideration?","opts":["Scheduling that accounts for carbon credit costs in the project budget","Scheduling compute-intensive workloads (batch processing, CI/CD builds, large data migrations) to run when the electricity grid''s carbon intensity is lowest — typically when renewable energy is abundant — reducing the project''s carbon footprint without changing the deliverable","Carbon-aware scheduling is only relevant for environmental organizations","A project scheduling technique that accounts for travel emissions from team travel"],"a":1,"exp":"Technology projects have compute footprints. Batch processing, ML training runs, and data migrations can be scheduled to align with grid carbon intensity — running at times when solar or wind is producing surplus. Cloud providers increasingly offer carbon-aware APIs. For PM practice, this means considering compute scheduling as an ESG deliverable, not just a technical optimization.","competency":"pm:governance"},
{"q":"A team member tells you that their manager pressured them to mark project tasks as complete before they actually were, to make the project look on track for the quarterly board review. What is your obligation as PM?","opts":["Accept the status updates and move on — reporting is subjective","Tell the team member to comply with their manager''s instruction","Document the situation, raise it through appropriate channels (your manager, PMO, or compliance hotline), refuse to incorporate inaccurate status in official reports, and protect the team member from retaliation — falsifying project status is a professional ethics violation and potentially a governance compliance issue","Discuss it informally and take no formal action"],"a":2,"exp":"Falsifying project status reports is a direct violation of PMI''s Code of Ethics (honesty and transparency obligations) and may constitute financial reporting fraud if the board uses project status in investor disclosures. The PM has a whistleblower-equivalent obligation: document, escalate through appropriate channels, refuse to sign inaccurate reports, and protect the team member who brought the information forward.","competency":"pm:governance"},
{"q":"What is the purpose of an AI governance acceptable use policy on a project that deploys AI-assisted decision making?","opts":["To restrict all AI use until formal regulation is in place","To define the boundaries of acceptable AI use: which decision types can be AI-assisted vs. which require human decision-making, what AI outputs must be disclosed to affected parties, how AI errors will be detected and corrected, and who is accountable when AI-assisted decisions cause harm — providing a governance framework that protects the organization and those affected by AI outputs","To prevent competitors from knowing the project uses AI","An acceptable use policy is only needed for customer-facing AI, not internal PM tools"],"a":1,"exp":"AI acceptable use policies prevent governance gaps. Without them, AI is deployed inconsistently — some teams defer all decisions to AI, others ignore it entirely. The policy defines: human-in-the-loop requirements, disclosure obligations, error correction processes, and accountability assignment. The PM ensures the policy exists before AI tools are used in consequential project decisions.","competency":"pm:governance"},
{"q":"What is data classification, and why must a PM understand it as a project governance requirement?","opts":["Data classification is an IT function with no PM implications","Data classification categorizes organizational data by sensitivity (public, internal, confidential, restricted/highly confidential) — the PM must understand which data classification levels are present in the project because they determine: security controls required, access restrictions, storage requirements, retention policies, and vendor data handling obligations","Data classification only applies to government and defense projects","Data classification is managed by the information security team after the project is complete"],"a":1,"exp":"Data classification has direct project implications. A project handling restricted (e.g., personal health) data requires: encryption at rest and in transit, restricted access controls, DPIA completion, vendor DPA agreements, and potentially on-premises processing. The PM must identify data classification during scoping — discovering it at architecture review or go-live creates rework, delay, and compliance risk.","competency":"pm:governance"},
{"q":"What audit trail requirements does a PM need to maintain for a project that involves financial system changes?","opts":["Audit trails are only needed if the project is audited by an external party","Audit trails are only the finance team''s responsibility","The PM must ensure the project maintains complete, tamper-evident records of: all change requests and approvals, test results and sign-offs, data migration validation records, system access logs, key decisions and who made them, and go-live authorization — sufficient to support post-implementation audit without reliance on participant memory","Only financial transactions require audit trail documentation; project management activities do not"],"a":2,"exp":"Financial system changes are subject to SOX, internal audit, and regulatory examination. Auditors reconstruct what happened from evidence, not from team members'' recollections. The PM''s audit trail includes: change control records, test evidence, access control documentation, data migration validation, and go-live authorization. Gaps in any of these create audit findings that may require system remediation or financial restatement.","competency":"pm:governance"},
{"q":"The PMI Code of Ethics requires PMs to report accurate project status. A senior stakeholder pressures you to present an optimistic picture at the board meeting because ''there are investors in the room.'' What is the correct PM response?","opts":["Comply with the stakeholder''s request to maintain the relationship","Present whatever the sponsor approves — it is their project","Decline to present inaccurate information: explain that your professional obligation requires accurate reporting; offer to work with the stakeholder to frame the status constructively (acknowledging challenges while presenting credible recovery plans) but refuse to misrepresent material project facts — if the pressure continues, escalate through compliance channels","Agree and add a disclaimer that the presentation is forward-looking"],"a":2,"exp":"PMI Code of Ethics, Honesty standard: PMs must provide accurate information. Investor-facing misrepresentation may also constitute securities fraud. The PM can frame status constructively (''we are addressing X challenge with Y recovery plan'') without fabricating positive outcomes. If the stakeholder insists on material misrepresentation, this is an ethics escalation — not a communication style disagreement.","competency":"pm:governance"},
{"q":"What is a conflict of interest in project management, and what is the PM''s obligation when one arises?","opts":["A conflict of interest occurs when two stakeholders disagree on project scope","A conflict of interest arises when a PM''s personal interests (financial, personal relationships, outside affiliations) conflict or appear to conflict with their professional duty to the project or organization — the PM must proactively disclose the conflict to the appropriate authority, recuse themselves from affected decisions, and document the disclosure and recusal","Conflicts of interest are only relevant for procurement decisions","A conflict of interest only needs to be disclosed if it is financial"],"a":1,"exp":"PMI''s Code of Ethics requires proactive conflict disclosure, not just reactive response when caught. Appearing to have a conflict of interest (e.g., your spouse works for a vendor being evaluated) can damage organizational trust even without actual impropriety. Disclose early, recuse from the affected decision, and document — protecting both the organization and yourself.","competency":"pm:governance"}
]'::jsonb);

-- ── MODULE 18: PM Career Acceleration & PMP ───────────────────────────────────
SELECT pg_temp.fill_pm_exam_b(18, '[
{"q":"You have a 4-year university degree, 3 years of project management experience leading projects, and a 36-hour PM training course. Are you eligible to apply for the PMP certification?","opts":["No — you need 5 years of experience with a university degree","Yes — a 4-year degree requires 36 months of PM experience leading projects and 35 hours of PM education; you meet all three requirements","No — the 36 hours must be completed within the last 12 months","Yes — but only if all experience was on Agile projects"],"a":1,"exp":"PMP eligibility: With a 4-year degree: 36 months of PM experience leading projects + 35 hours of PM education. With a high school diploma or secondary education: 60 months of PM experience + 35 hours education. You have a 4-year degree, 36 months (3 years) of experience, and 36 hours of training (above the 35-hour minimum). You are eligible.","competency":"pm:career"},
{"q":"The PMP exam consists of how many questions, and approximately what split between predictive and agile/hybrid content?","opts":["200 questions, 70% predictive / 30% agile","180 questions, approximately 50% predictive approaches and 50% agile or hybrid approaches — reflecting PMI''s recognition that modern PM requires both","150 questions, 100% PMBOK knowledge-based","220 questions, 80% agile / 20% predictive"],"a":1,"exp":"PMP (as of the 2021 update): 180 questions, 230-minute time limit, with approximately 50% of questions covering predictive (waterfall) approaches and 50% covering agile and hybrid approaches. The exam tests application and analysis, not just knowledge recall. Scenario-based questions require understanding how to apply PM concepts in context.","competency":"pm:career"},
{"q":"You are building your PM portfolio artifacts to demonstrate competency for a program manager role. Which artifact best demonstrates your ability to manage stakeholder complexity?","opts":["A copy of your PMP certificate","A project charter you wrote","A stakeholder engagement assessment matrix you created for a cross-functional transformation — showing how you tracked engagement levels, tailored communication strategies, and moved key resistors to supporters over a 12-month program","A Gantt chart from your most recent project"],"a":2,"exp":"Portfolio artifacts should demonstrate competency application in context, not just credentials. A stakeholder engagement assessment matrix with documented outcomes (resistor became champion, executive disengagement corrected) shows judgment, strategic communication, and results — qualities program manager roles require. Certificates demonstrate qualification; portfolio artifacts demonstrate capability.","competency":"pm:career"},
{"q":"What is the CAPM (Certified Associate in Project Management) certification, and who is it most appropriate for?","opts":["An advanced certification for experienced PMs with 5+ years","An entry-level PMI certification requiring 23 contact hours of PM education and no experience requirement — appropriate for students, career changers, or professionals early in their PM careers who want to demonstrate foundational PM knowledge","A certification equivalent to PMP for non-project managers","A certification that requires PMP as a prerequisite"],"a":1,"exp":"CAPM is PMI''s entry-level certification: 23 contact hours of PM education, no experience requirement, exam tests PMBOK knowledge. It is appropriate for those entering the PM profession who cannot yet meet PMP''s experience requirements. It demonstrates commitment to the profession and foundational knowledge to employers.","competency":"pm:career"},
{"q":"PRINCE2 Practitioner certification, compared to PMP, is distinguished by:","opts":["PRINCE2 is more widely recognized in the United States than PMP","PRINCE2 is a method-specific certification (UK/European origin) focused on a specific structured project management method with defined roles, processes, and themes; PMP is a practice-based certification demonstrating PM competency across methodologies — PRINCE2 is more prescriptive; PMP is more flexible and globally recognized","PRINCE2 requires less experience than PMP","PMP and PRINCE2 test identical knowledge areas"],"a":1,"exp":"PRINCE2 (Projects IN Controlled Environments) is a defined method with specific roles (Executive, Senior User, Project Manager), management products (project initiation document, exception report), and stages. It is dominant in UK government and European organizations. PMP is methodology-agnostic and globally recognized. Many international PMs hold both. PRINCE2 Practitioner validates ability to apply the PRINCE2 method in complex projects.","competency":"pm:career"},
{"q":"You are optimizing your LinkedIn headline for PM roles. Which headline is most effective?","opts":["''Project Manager''","''PMP-Certified Project Manager | AI & Digital Transformation | $50M+ Delivered | Speaker''","''Senior Professional with Project Management Experience and Multiple Certifications''","''Looking for Project Manager Opportunities | Open to Work''"],"a":1,"exp":"LinkedIn PM headlines must be specific and searchable. Effective elements: credential (PMP signals qualification), specialization (AI & Digital Transformation = searchable niche), proof of scale ($50M+ delivered = business credibility), differentiator (Speaker = thought leadership signal). Generic headlines like ''Project Manager'' do not differentiate in a pool of 1M+ PM profiles.","competency":"pm:career"},
{"q":"You are negotiating salary for a senior PM role. The employer offers $115,000. Your research shows the market range is $120,000–$145,000 for your experience and location. What is the most effective negotiation strategy?","opts":["Accept immediately to avoid seeming difficult","Counter with $150,000 to anchor high and split the difference","Decline the offer without countering","Present your market research ($120K–$145K range), anchor at $138,000 with specific justification (your delivery record, certifications, and market data), and state your walk-away point internally — knowing your BATNA strengthens your position"],"a":3,"exp":"Salary negotiation: (1) research the market range before negotiating, (2) anchor above your target (anchoring at $138K gives room to land at $130–135K), (3) justify with data (market research + your specific value), (4) know your BATNA (another offer or your current salary gives real walk-away power). Accepting the first offer leaves money on the table; countering without data appears uninformed.","competency":"pm:career"},
{"q":"What is the PMI Talent Triangle, and which domain covers emotional intelligence, communication, and leadership?","opts":["The Talent Triangle has two domains: technical and leadership","The PMI Talent Triangle has three domains: Ways of Working (delivery approaches and methods), Power Skills (formerly Leadership — covering communication, emotional intelligence, collaborative leadership, and strategic thinking), and Business Acumen (organizational strategy, benefits realization, and financial literacy) — Power Skills covers emotional intelligence and leadership","The Talent Triangle is a tool for assessing team talent gaps","The Talent Triangle applies only to program managers, not project managers"],"a":1,"exp":"PMI updated the Talent Triangle in 2022: Ways of Working (predictive, agile, hybrid delivery methods), Power Skills (leadership, communication, EQ, negotiation — formerly ''Leadership''), and Business Acumen (strategy, finance, organizational alignment). PMPs must earn PDUs across all three to maintain certification, reflecting the shift from purely technical PM knowledge to holistic professional capability.","competency":"pm:career"},
{"q":"You are a project coordinator targeting a PM role in 18 months. What is the most evidence-based career progression plan?","opts":["Complete as many certifications as possible in 18 months","Request to be assigned as PM on a small project immediately, seek a mentor who is a senior PM, pursue CAPM or PMP (once eligible) to validate your knowledge, document quantified project outcomes for your portfolio, and aim to demonstrate 3 key PM competencies (stakeholder management, risk management, communication) in real project work","Wait for a promotion to PM before taking on PM responsibilities","Focus exclusively on Agile certification to maximize job market appeal"],"a":1,"exp":"PM career progression is built on three simultaneous tracks: (1) experience — take real PM responsibility on projects of increasing complexity; (2) credentials — validate knowledge through CAPM → PMP as experience allows; (3) portfolio — document outcomes with metrics (on-time delivery, risk prevented, stakeholder satisfaction). Credentials without experience are insufficient; experience without credentials limits interview success; both without a documented portfolio is invisible.","competency":"pm:career"},
{"q":"What is the PM career ladder in a mature organization, and what competency shift occurs between Senior PM and Program Manager?","opts":["The career ladder is: Analyst → PM → Director → VP — no competency shift at any level","Coordinator → PM → Senior PM → Program Manager → PMO Director/VP Delivery. The shift from Senior PM to Program Manager moves from single-project delivery excellence to multi-project strategic coordination: managing interdependencies, benefit realization across projects, stakeholder influence at portfolio level, and developing other PMs","The career ladder is flat — all PM levels have the same competency requirements","Program Manager and PMO Director are the same role"],"a":1,"exp":"The Senior PM → Program Manager shift is a strategic competency pivot: from ''I deliver this project'' to ''I coordinate these projects to realize this strategic benefit and develop the PMs who run them.'' Program managers must manage ambiguity at portfolio level, influence without direct authority across multiple project teams, and be accountable for outcomes that span organizational boundaries.","competency":"pm:career"},
{"q":"A junior PM asks how to demonstrate value beyond on-time, on-budget delivery. What is your advice?","opts":["On-time and on-budget are the only PM success measures — focus on those","Junior PMs should not worry about value demonstration","Document and communicate the business outcomes your projects enabled: customer satisfaction improvement, cost savings achieved, new revenue generated, risk prevented, and time-to-market acceleration — connect project delivery metrics to business impact metrics, and present these in post-project benefit reviews","Ask the sponsor to write a recommendation letter"],"a":2,"exp":"On-time and on-budget are table stakes — they demonstrate competence, not strategic value. Business outcome metrics (cost saved, revenue enabled, risk averted) connect PM work to organizational results that matter to executives. PMs who track and communicate these become business partners; those who only report schedule and cost remain tactical operators.","competency":"pm:career"},
{"q":"What role do AI tools play in the future-proofed PM toolkit, and what is the PM''s responsibility in using them?","opts":["AI tools will replace project managers within 5 years — invest in other careers","AI tools are not reliable enough for PM use — avoid them","AI tools augment PM capability: intelligent scheduling (auto-critical path), risk pattern detection, communication sentiment analysis, meeting intelligence, and portfolio analytics. The future-proofed PM uses AI to increase analytical capacity and reduce administrative burden, while maintaining human judgment for stakeholder decisions, ethical choices, and creative problem-solving — and stays current by continuously evaluating new tools","AI tools should only be used by senior PMs with appropriate experience"],"a":2,"exp":"AI amplifies PM capability — it does not replace PM judgment. Intelligent scheduling, AI risk identification, and communication analytics free PMs from administrative tasks to focus on leadership and strategy. The responsibility: validate AI outputs, maintain human oversight of AI-assisted decisions, understand what the AI is and is not doing, and continuously develop skills that AI cannot replicate: relationship intelligence, ethical judgment, and adaptive leadership.","competency":"pm:career"},
{"q":"You are preparing lessons learned documentation at project closure. What makes lessons learned actually useful for future projects?","opts":["Documenting everything that went wrong in detail","Lessons learned that are actionable: specific (what exactly happened), causal (why it happened), and prescriptive (what future PMs should do differently or repeat) — organized by project phase and searchable in the PMO repository","A summary report submitted to the PMO and never reviewed","An exit interview with the project manager"],"a":1,"exp":"Lessons learned fail when they are vague (''communication could have been better'') or unactionable. Effective format: ''In Week 8, API documentation from Vendor X was 3 weeks late, delaying integration testing (what). Root cause: no contractual milestone for API documentation delivery (why). Recommendation: include API documentation delivery as a contractual milestone with SLA in all vendor integrations (prescriptive).'' Stored and searchable in the PMO library, this actually prevents future failures.","competency":"pm:career"},
{"q":"What is the Business Acumen domain of the PMI Talent Triangle, and why has it been elevated as a PM competency?","opts":["Business Acumen covers project scheduling and cost management","Business Acumen is the domain covering organizational strategy alignment, benefits realization management, financial literacy (ROI, NPV, IRR), market awareness, and understanding how the project creates enterprise value — elevated because PMs who understand business context make better scope, risk, and trade-off decisions than those who optimize purely for delivery metrics","Business Acumen is only relevant for PMO Directors","Business Acumen means PMs should be able to do the work of CFOs"],"a":1,"exp":"PMI elevated Business Acumen because delivery-focused PMs who do not understand the business case they are delivering make suboptimal decisions: they over-engineer solutions, miss opportunities to accelerate key value drivers, and cannot credibly advise sponsors on strategic trade-offs. A PM who understands NPV, competitive positioning, and customer value can have fundamentally different (better) conversations with executives.","competency":"pm:career"},
{"q":"You have completed your PMP and want to maintain it over the next 3 years. What are the PDU (Professional Development Unit) requirements?","opts":["60 PDUs total in any category you choose","60 PDUs over 3 years, distributed across the PMI Talent Triangle: minimum 8 PDUs in each of the three domains (Ways of Working, Power Skills, Business Acumen), with the remaining PDUs flexible across all domains","30 PDUs per year, exclusively from PMI-approved courses","120 PDUs in 3 years with no domain minimums"],"a":1,"exp":"PMP maintenance: 60 PDUs per 3-year cycle. PDU minimums per domain: 8 PDUs in Ways of Working, 8 PDUs in Power Skills, 8 PDUs in Business Acumen (24 minimum across three domains). Remaining 36 PDUs can be distributed across any domain. PDUs are earned through: education (courses, webinars, conferences) and giving back (volunteering, mentoring, writing, speaking).","competency":"pm:career"}
]'::jsonb);

-- Verification
SELECT ch.order_index, ch.title, COUNT(qq.id) as question_count
FROM public.quiz_questions qq
JOIN public.quizzes qz ON qq.quiz_id = qz.id
JOIN public.chapters ch ON qz.chapter_id = ch.id
JOIN public.courses co ON ch.course_id = co.id
WHERE co.title = 'AI Project Manager & Delivery Leader'
  AND ch.order_index IN (10, 11, 12, 13, 14, 15, 16, 17, 18)
GROUP BY ch.order_index, ch.title
ORDER BY ch.order_index;
-- Expected: 9 rows, each with question_count = 15
